quests[96276] = { id = 96276, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Charms", description = "De Children of Ula'tek play cruel games on de spirits here. Dey use dark charms to keep dem trapped and tormented.\n\nDe charms are hidden throughout de temple. Find and burn them, so de spirits here can find peace.", sourceObjective = "Burn 20 Dark Charms found throughout the Vaults of Atal'Utek.", completion = "De ancestors' spirits see what ya done, and dey are pleased!", sourceObjectiveStatus = "unverified-source-field" }
quests[96293] = { id = 96293, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mush-Vroom!" }
quests[96295] = { id = 96295, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Pertinent Punishment" }
quests[96305] = { id = 96305, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Innocent Essence", description = "When de defenders fell, cursed to their fate, so too did de great eagle Tok'jara who flew with dem. Such innocence did not deserve dis curse.\n\nEven now, de spirit struggles to break free, forming a twisting geyser as it rises from the venomous pools.\n\nHelp it be free, claim its essence from the poison, and end its suffering.", sourceObjective = "Recover 15 Essence of Tok'jara from the venom geyser.", completion = "Your action, {name}, warms dis old troll's heart. The spirit of Tok'jara is free and will travel dis world by your side.", sourceObjectiveStatus = "unverified-source-field" }
quests[96307] = { id = 96307, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Special Assignment: Wraith Wrath" }
quests[96310] = { id = 96310, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disrupting the Order", description = "Great work defeating their forces. Every step we take will keep Azeroth safe.\n\nBut usurpers are still trying to seize control. Baraat has already spotted high ranking domanaar looking at the remaining resources.\n\nWe need to defeat the Umbrawardens and any of their forces along the way.", sourceObjective = "Slay 3 domanaar Umbrawardens and any of their forces around Val.", progress = "We will not allow them to regain their foothold.", completion = "With their forces hindered and leaders slain, this base is further degraded. \n\nGreat work, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[96329] = { id = 96329, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hexes and Hoaxes" }
quests[96338] = { id = 96338, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Port of Entry", description = "{name}, take a look at that platform above. What do you think they use that for?\n\nThe void creatures steal wildlife from Azeroth and move them here to be broken, then added to their forces. That platform must be where creatures are first brought in.\n\nLet's force our way through any defenses up there and destroy that portal!", sourceObjective = "Travel to the Transit Platform and destroy the primary transport portal.", progress = "Their supply chain must be severed. If we can do that, we may be able to end the threat here for good.", completion = "The domanaar operation has been severely stifled, but we will find no peace while these wicked creatures persist.", sourceObjectiveStatus = "unverified-source-field" }
quests[96349] = { id = 96349, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ancestral Gems", description = "When de Children of Ula'tek seized dis temple, many of my ancestors died defendin' it. Sacred relics were seized by de snakes! Even now, dey twist those items into foul magic!\n\nAmong these items were some gems of great power.\n\nSearch de vaults, ritual chambers, and every deep corner of de temple and recover any gems you find.", sourceObjective = "Recover 30 Ritual Gems from the deepest interiors of the Vaults of Atal'Utek.", progress = "Have you recovered de gems?", completion = "De Children of Ula'tek won't be meddlin' with these gems anymore. I won't forget dis deed.", sourceObjectiveStatus = "unverified-source-field" }
quests[96352] = { id = 96352, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Charms", description = "De Children of Ula'tek play cruel games on de spirits here. Dey use dark charms to keep dem trapped and tormented.\n\nDe charms be hidden throughout de temple. Find and burn them, so de spirits here can find peace.", sourceObjective = "Burn 20 Dark Charms found throughout the Vaults of Atal'Utek.", completion = "De ancestor's spirits see what ya done, and dey are pleased!", sourceObjectiveStatus = "unverified-source-field" }
quests[96354] = { id = 96354, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Balance Paid in Blood", description = "De Children of Ula'tek have upset de balance of de spirit world. Many spirits be angry and demand justice before dey can move on.\n\nDe snakes' blood will restore de balance!\n\nSlay de Children of Ula'tek and all dat aid dem here in de temple.", sourceObjective = "Slay enemies within the Vaults of Atal'Utek.", completion = "De spirits see what ya done, and rest now in de balance you have brought.", sourceObjectiveStatus = "unverified-source-field" }
quests[96360] = { id = 96360, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wading In", description = "Too many spirits here have succumbed to de dark charms of Nek'zali, but there's still hope to save others.\n\nPlace spirit guardians throughout de lakes of venom so dey may offer sanctuary to spirits nearby. \n\nDe venom lakes are deadly, so go prepared!", sourceObjective = "Place 8 Spirit Guardians at locations in the venom.", completion = "De spirits whisper to me. Dey are thankful for de safety ya give them.", sourceObjectiveStatus = "unverified-source-field" }
quests[96361] = { id = 96361, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cursed Existence", description = "When de poison spread through dis temple, many of our ancestors fell trying to defend dis place.\n\nNow Nek'zali has ensnared their spirits to serve her in restoring Ula'tek. Put de cursed spirits to rest so dey may pass beyond dis place.", sourceObjective = "Slay Jarza the Cursed, Venomous Revenant Zal'kir, Coil-Cursed Vok'tara, and other servants of Nek'zali.", completion = "Ya brought merciful peace to the ancestors with dis deed.", sourceObjectiveStatus = "unverified-source-field" }
quests[96382] = { id = 96382, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A New Approach", description = "For this threat, you'll need to think more like the domanaar. Luckily, I can do just that.\n\nWhat we need is a puppet. Someone we can give the reins who has no aspirations for your precious Azeroth. Those new domanaar you saw will need evaluation.\n\nTake this veil. You'll be able to blend in and observe them. I understand your urge to strike, but be patient. The time will come to eliminate all in your path, as your kind seems to enjoy.\n\nSee if you can find a proper candidate.", sourceObjective = "Observe the new domanaar Umbrawardens and select a proper candidate for the plan.", completion = "Hm... yes. Impotus sounds like someone we can work with.", sourceObjectiveStatus = "unverified-source-field" }
quests[96388] = { id = 96388, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Joining the Abyss Anglers", description = "Ya ever heard of de Abyss Anglers?\n\nForest tribes have been hunting de land as well as de waters for generations.\n\nDon't be shy, hash'ura. Grab a suit and go for a dive!", sourceObjective = "Talk to Depthdiver Jeju to join an Abyss Anglers dive. \n\nCatch any 3 fish with your harpoon, recover 1 Sunken Artifact, and use the Surface! ability to return safely.", progress = "De suit fit okay?", completion = "Ya a natural diver, hash'ura!\n\nHere are a few Angler Pearls too. Collect enough and bring them back to me or Tu'nakit to prove ya ready for better gear!", sourceObjectiveStatus = "unverified-source-field" }
quests[96389] = { id = 96389, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Place to Negotiate", description = "While you were attuning the gem to the Void, I managed to acquire one of Impotus's projection devices. \n\nWe're going to use it to lure him to us, then prevent him from escaping with the gem. \n\nNot here, though. Let us find somewhere more discrete.", sourceObjective = "Meet with Leona Darkstrider in the Steam Ravine.", completion = "Good. Now we just need to convince Impotus to show up.", sourceObjectiveStatus = "unverified-source-field" }
quests[96400] = { id = 96400, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lingering Corruption" }
quests[96410] = { id = 96410, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeking Knowledge Week 1 of 5: The Omnium Folio", description = "Those who sought to learn from the Omnium had to contribute to it.\n\nWhile most Magisters studied within the Terrace, a select few were appointed as \"Seekers of Wisdom.\"\n\nSeekers would search for new and foreign magic to contribute to the Omnium's vast index for study.\n\nGiven your... adventurous experience, I think you'd make an excellent seeker.\n\nIf you're interested, the Grand Magister will explain more.", sourceObjective = "Retrieve your Omnium Folio from Grand Magister Rommath and empower your first rune.", progress = "Whether it was magical theories, complicated rune-work, or harvested samples of magic, the Omnium was built to preserve knowledge so that future Magisters could learn, harness, and master the work of those that came before them.", completion = "While we don't expect you to master the very secrets of the Void or fire, we have chosen some beneficial runes to assist you in battle.\n\nWith each weekly research assignment you contribute, Umbric and I will select another series of runes for your Omnium Folio.\n\nFor now, test out your new rune while Umbric and I prepare the next assignment for you.", sourceObjectiveStatus = "unverified-source-field" }
quests[96432] = { id = 96432, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Power Overload" }
quests[96433] = { id = 96433, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not the Mama" }
quests[96439] = { id = 96439, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gone Dark", description = "These infernal nests are where de Children of Ula'tek spawn from. We must work to clear dem out if we are to have any hope of stemming de endless tide of snakes.\n\nI have been sending groups of my most fearless scouts to gather information on dem. All have returned... except for one.\n\nGo, track down Ulantu and Naj'kula in de Blistering Terrace. Find out why dey gone dark.", sourceObjective = "Track down Scout Ulantu and Scout Naj'kula in the Blistering Terrace.", completion = "Kul'amara sent you?\n\nBless de will of our wily loa...", sourceObjectiveStatus = "unverified-source-field" }
quests[96440] = { id = 96440, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Victory Within Hindsight", description = "Great work, {name}! I can already picture the walls of the Acropolis crumbling.\n\nIn fact, why don't we head there now and press our advantage? The Light can shine through the tiniest of cracks.\n\nI'll scout ahead and meet you on the way there.", sourceObjective = "Meet Baraat at the Glacial Reservoir portal.", completion = "It seems we're back to where we began. \n\nThese covetous monsters won't hesitate to steal whatever power they can find, even from each other. \n\nWe'll need a new plan.", sourceObjectiveStatus = "unverified-source-field" }
quests[96441] = { id = 96441, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeking Knowledge Week 2 of 5: Ritualized Arcana", description = "The nature of the Dawnwell has sparked a question among the minds of Magisters' Terrace:\n\nIf magic can corrupt and suffuse other magics, how will the Dawnwell affect the ley lines branching out from it?\n\nWith inquiry, comes experiment.\n\nThe Ritual Sites in Quel'Thalas use the ley lines to fuel their magic.\n\nDisrupt these sites and retrieve samples of the arcana you find.", sourceObjective = "Collect 8 Ritualized Arcana.\n\nArcana can be found in either Daggerspine Point or Broken Throne Ritual Sites on any difficulty.", progress = "We've all been asking what sort of effects the Dawnwell will have on the ley lines of Quel'Thalas.\n\nThe byproduct of these ritual sites may indicate just how deep these external magics go.", completion = "It appears Magister Umbric's theory was correct. The rituals have seared the very fabric of the arcana, both overcharging yet depleting it entirely.\n\nPerhaps similar accounts have been recorded within the Omnium.\n\nThe Magisters assigned to studying these samples have quite the work cut out for them.\n\nWhile you wait, take a look at the new runes we've outlined for you.", sourceObjectiveStatus = "unverified-source-field" }
quests[96442] = { id = 96442, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeking Knowledge Week 3 of 5: Ley Line Assaults", description = "Unfortunately, most of the measurable samples were expunged by the Ritual Site's excessive energy.\n\nIf we are to accurately measure the various magics seeping into the ley lines, we'll need samples from a broader, less concentrated source.\n\nI am told the Farstriders continue to route the void strikes across Quel'Thalas.\n\nBring me coalesced ley energy from any of the assaulting forces.", sourceObjective = "Collect 5 Dark-Ley Coalescence by completing any Void Assault in Eversong or Zul'Aman.", progress = "The arcana you retrieved from the Ritual Sites was indicative of an excessive enervation of ley energy.\n\nRommath theorizes the magic used in these assaults will provide a similar metric of measurement, without the depleted burnout.", completion = "Whether it's void-flecked, or entwined with foreign strands of arcane, the ley energy you brought will get us a more accurate reading.\n\nIdeally, we can determine the sort of impact these magics have on our ley lines to help us discover what that means for the Dawnwell.\n\nReturn to us later. There's work to be done here and new runes for you to examine.", sourceObjectiveStatus = "unverified-source-field" }
quests[96443] = { id = 96443, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeking Knowledge Week 4 of 5: Magical Primessence", description = "Thanks to your efforts, we've isolated the effects of trace amounts of foreign magic coalescing with the ley lines.\n\nOur next phase is to compare these results against a pure sample of magic coalescing with the same energy.\n\nYour task is to track down a primessence of magic--be it arcane, Void, Light, or other--and acquire it from its deadly source.\n\nGood luck, {name}.", sourceObjective = "Collect 1 Primessence of Magic from any final dungeon or delve boss, Illustrious Contender's Strongbox, or the Sporefall raid.", progress = "If we can measure the effects of trace amounts of magic and more potent sources of magic coalescing with Quel'Thalas's ley energies, we may be able to predict what that means for the Dawnwell.\n\nAnd due to the Dawnwell's unique properties, any prime source of magic will suffice--well, for our tests anyways.", completion = "<Umbric's eyes widen as he carefully takes the primessence from you.>\n\nAn astounding find, {name}.\n\nAlthough such a potent source of magic wasn't directly infused into the Dawnwell, this will more than suffice for our isolated tests.\n\nI'd let you observe, but I'm afraid there's a lot of theory crafting and formula writing involved before anything exciting happens.\n\nTake stock of the new runes we've chosen for you. I think you'll enjoy this week's selection.", sourceObjectiveStatus = "unverified-source-field" }
quests[96444] = { id = 96444, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeking Knowledge Week 5 of 5: Off-World Magic", description = "Although it made an excellent catalyst, the primessence you retrieved revealed a factor we did not account for.\n\nThe alien nature of the Void and ethereal magic used in their assaults proved incompatible with the experiment.\n\nWe need a sample of their magic if we are to make any progress--not from the assaults here in Quel'Thalas, but from the source of their attacks.\n\nI am told these enemies strike from off-world staging grounds. Good luck, {name}.", sourceObjective = "Recover 1 fragment of alien magic from an elite creature on Val or Naigtal.", completion = "<Rommath narrows his eyes at the swirling mote of magic you brought him before glancing at Umbric.>\n\nI won't question how you possibly could've gotten your hands on such a... foreign source of magic like this, but this is precisely what we'll need to continue our tests.\n\nYour role as seeker has been indispensable to our efforts. In exchange, Umbric and I have laid the last of the runes we've set aside for you. \n\nHave a look.", sourceObjectiveStatus = "unverified-source-field" }
quests[96446] = { id = 96446, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spark of Tides", description = "A vision of tides permeates your mind.\n\nEldara Dawnrunner might have more information regarding these Sparks of Tides.", sourceObjective = "Speak to Eldara Dawnrunner in Silvermoon.", completion = "This is a Spark of Tides.\n\nEvery week, one of these sparks will appear while on your adventures. In its current state, it's rather useless, but acquiring more will allow you to craft powerful items. Reagents like these are malleable, robust, and the prize for many crafters.\n\nThis is a unique crafting material that can help an item achieve expertise beyond that of mortal ability.", sourceObjectiveStatus = "unverified-source-field" }
quests[96450] = { id = 96450, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sideways", description = "Naj'kula and I were here to observe how the Children of Ula'tek reproduce.\n\nWe discovered dis lich, Lokago. Malacrass had him experimentin' on kidnapped Amani. I stole his records to try and figure out why, but de lich discovered us. I was injured. I dropped everythin'.\n\nNaj'kula was right behind me... We gotta recover de notes--and find Naj'kula!", sourceObjective = "Find the lich's notes and look for signs of Naj'kula.", progress = "I lost everything. But if we find anything, I hope it's Naj'kula.", completion = "<Ulantu looks through the lich's notes.>\n\nDey are all here, but Naj'kula is not...", sourceObjectiveStatus = "unverified-source-field" }
quests[96451] = { id = 96451, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Child of Ula'tek", description = "I don't like dis. We should have found her by now.\n\n<Ulantu's face is sweaty and pale. She rubs her wound absentmindedly.>\n\nDe lich must have dragged her back to where he was doin' his experiments. And if his notes are to be believed...\n\nWe need to find Naj'kula quickly--or she may not be who she was.", sourceObjective = "Find Naj'kula, assist her, then return to Ulantu with proof.", completion = "<Sweat beads on Ulantu's forehead. She growls slightly in pain and can now barely walk.>\n\nKuku... I shoulda seen it. I shoulda gotten us out of here.", sourceObjectiveStatus = "unverified-source-field" }
quests[96457] = { id = 96457, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nothing Must Remain", description = "You saw what he did to Naj'kula. And who knows how many others.\n\n<Ulantu is sweating and pale, gripping her stomach.>\n\nToo many lives were sacrificed in de name of these awful... whatever Kuku became.\n\nIf only we could have killed de damned lich! But we can destroy his lab.", sourceObjective = "Use Naj'kula's Flame Amulet to destroy objects in Lokago's lab.", progress = "I feel de poison in my veins. Hurry now.", completion = "Thank you. Only one trace of Lokago's work remains.", sourceObjectiveStatus = "unverified-source-field" }
quests[96458] = { id = 96458, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Last Promise", description = "Lokago cut me with de same venom that twisted Naj'kula. I feel it burnin' me just the same.\n\nI intend to die an Amani. But my work is unfinished.\n\nPlease get these notes to Kul'amara.\n\nTell her she can find me at Naj'kula's side.", sourceObjective = "Deliver Ulantu's notes to Kul'amara.\n\nProvided item:", completion = "What's wrong? Is this about Ulantu and Naj'kula? \n\n<Kul'amara leafs through the pages. Her eyes widen.>\n\nThank you for bringing me dis, hash'ura. My scouts may be gone, but de information they died for will save lives.", sourceObjectiveStatus = "unverified-source-field" }
quests[96466] = { id = 96466, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Anguish Island", description = "Something is driving these creatures into our realm.\n\nI have sent one of my most capable servants to this \"Isle of Fangs\". Go and see what you can make of this den of snakes. In any other endeavor I would accompany you, of course--but I shall remain here. \n\nThis island sounds like a most dreadful place.\n\nDo have fun, though.", sourceObjective = "Meet Sanctum Attendant Ethrandil in Tokka's Landing.", progress = "I hate it here.", completion = "Snakes. \n\nWhy'd it have to be snakes?", sourceObjectiveStatus = "unverified-source-field" }
quests[96467] = { id = 96467, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thirst for Knowledge", description = "Two brothers came with us to dis cursed place... Zei'ka and Jun'ka.\n\nZei'ka, he got de fire in him. Soon as we landed, he ran off, chasing whispers like dey were calling his name. But, Jun'ka, he ain't a fool. He went after his brother, tryin' to keep him from getting himself killed.\n\nI don't like dis. Dis island, it'll swallow us whole if we ain't careful. Go check on dem, eh?", sourceObjective = "Meet with Zei'ka and Jun'ka at the Whispering Marsh.", completion = "Heh... Kul'amara worries too much. Dis island ain't here to scare us--it's here to be understood!", sourceObjectiveStatus = "unverified-source-field" }
quests[96469] = { id = 96469, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Crypt of the Disgraced", description = "Jun'ka's my brother, but he frets too much to let me chase after my life's dream.\n\nEver since I was a child, I wanted to learn more of our history. While much of it is told by de talespinners back home, they always skipped one thing: Atal'Utek. De more I dug, de more mysterious it became, and de more I became engrossed.\n\nNow, de scouts tell me that this crypt is filled with tablets inside. Tablets that could have de history of our people. I need to see those tablets, even if it kills me. You in?", sourceObjective = "Assist Zei'ka in traversing the Crypt of the Disgraced and retrieve the tablets.", progress = "What are you waiting for! Knowledge awaits!", completion = "Oi! Why do the walls hafta be crumblin' down now?!\n\nYou all gotta leave... but the tablets!", sourceObjectiveStatus = "unverified-source-field" }
quests[96471] = { id = 96471, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crumble and Tumble", description = "Blast it all! I dragged y'all into dis muck just 'cause my brother's worried about my hide!\n\nYou're gettin' outta here quick! I lead, you follow, and don't lag behind, or you're squashed!", sourceObjective = "Escape the Crypt of the Disgraced.", completion = "Thanks... thanks for stickin' with Zei'ka's antics back there. I'm... happy you're safe.\n\n<Jun'ka chokes up.>\n\nDon't... don't mind me now. I need a bit of quiet... just to stew in my thoughts.", sourceObjectiveStatus = "unverified-source-field" }
quests[96472] = { id = 96472, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Nexus-Captain", description = "The Hal'hadar may not know we are here yet, but they still hold the advantage.\n\nNexus-Captain Leth'ir and his associate, Mertei, are just over this ridge and surrounded by a small army.\n\nIf you can rally enough allies and catch their leaders off guard, we will deal a devastating blow before they know what hit them.\n\nProceed with caution, {name}, and make sure you are not alone.", sourceObjective = "Defeat Nexus-Captain Leth'ir.", progress = "What news of the Hal'hadar?", completion = "You were successful? Leth'ir is dead?\n\n<Riftblade Maella offers a rare smirk.>\n\nThe Hal'hadar may know we are here now, but the death of their Captain will have them scurrying through the swamp.\n\nYour deeds have bought us, and Azeroth, a chance to breathe.\n\nTake a moment to rest while you can. The threat here is far from finished.", sourceObjectiveStatus = "unverified-source-field" }
quests[96473] = { id = 96473, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Imperator Pertinax", description = "Like all domanaar, Imperator Pertinax sees himself only as a predator and never the prey.\n\nUnfortunately, our prey is well-guarded in his Void Acropolis.\n\nIf you manage to gather enough allies and catch the imperator off guard, we'll deal a crushing blow to our enemies.\n\nMove swiftly and cautiously, {name}, and ensure you have backup before engaging Pertinax.", sourceObjective = "Defeat Imperator Pertinax in the Void Acropolis.", progress = "Yes, my delightful little mortal? What fascinating news do you have for me?", completion = "The mighty imperator has fallen?\n\nOh, Pertinax... caught off guard in your own fortress?\n\nHow deliciously embarrassing!\n\nYou have dealt a considerable blow to a formidable enemy and we've only just arrived! Well done!\n\nThere will be more chaos to unleash soon enough...", sourceObjectiveStatus = "unverified-source-field" }
quests[96474] = { id = 96474, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Something for Astalor", sourceObjective = "Investigate the nearby rock for Attendant Ethrandil in Tokka's Landing.", progress = "Can we leave yet?", completion = "<Ethrandil sighs heavily.>\n\nOf course there are ghosts.", sourceObjectiveStatus = "unverified-source-field" }
quests[96475] = { id = 96475, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Captivating Science", description = "The domanaar Impotus sounds like he can be persuaded to set his sights elsewhere. \n\nSpeaking with them directly will be challenging. They are distrustful, even of one another, as you can see from their projection devices. \n\nWe must set a trap.\n\nTake this soul gem and hunt the beings that inhabit the Acropolis. We will use the Void energy of this place against them.", sourceObjective = "Infuse the soul gem with void essence by defeating enemy forces in the Void Acropolis.", progress = "For prey like this, we need the right trap.", completion = "Ah, perfect! The gem has adapted to the rhythms of the Void.", sourceObjectiveStatus = "unverified-source-field" }
quests[96492] = { id = 96492, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Special Assignment: Demand and Supply" }
quests[96496] = { id = 96496, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Road Not Taken Twice", description = "During our surveys of this iced desert, our scouts identified two areas worth keeping an eye on, but with a major problem: they're only accessible through single points of entry.\n\nBefore I'm comfortable sending out more forces, we need to secure their exits.\n\nWe've been working on teleportation crystals for faster local travel that leverage the domanaar's existing portal network, and we're close to a solution. You just need to field test them.\n\nSet up these prototype rift slippers and report back.", sourceObjective = "Place Rift Slippers in the Forgotten Chamber and Void Acropolis.", progress = "We need those rift slippers in place to expand our operations through Val safely, and to prove the first step of our local teleportation network.", completion = "Excellent work returning in one piece. Now our scouts can move more freely without risk of being cornered.", sourceObjectiveStatus = "unverified-source-field" }
quests[96497] = { id = 96497, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spatial Reasoning", description = "The domanaar are more entrenched here than we thought and these storms refuse to relent even for a moment.\n\nWe've finally figured out how to hijack their portal network for short range traversal thanks to your efforts setting up the rift slippers. Now we just need help setting up our portal bridges.\n\nHere are four strategic locations, including this outpost, for you to set up the portal bridges. Once active, you'll be able to more swiftly respond to threats as they arise.\n\nTime to get to work.", sourceObjective = "Place Portal Bridges across Val.", progress = "Have you finished with the portal bridges?", completion = "Perfect. Now we can strike our foes at a moment's notice. \n\nThey'll never know what hit them.", sourceObjectiveStatus = "unverified-source-field" }
quests[96498] = { id = 96498, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grovewarden's Kris", sourceObjective = "Thank you for gathering these beautiful moths. Please accept this as thanks.", sourceObjectiveStatus = "unverified-source-field" }
