quests[96503] = { id = 96503, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: A Ghostly Nightmare", description = "It appears your scouting has born fruit. This power could prove a useful boon indeed. \n\nReturn to Atal'Utek and siphon its magic for our glorious purpose.", sourceObjective = "Get to the bottom of the ancient curse in the Coiled Isle.", progress = "You're still here?", completion = "I hope you haven't brought anything particularly nasty back with you.", sourceObjectiveStatus = "unverified-source-field" }
quests[96504] = { id = 96504, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warm Haranir Blanket", sourceObjective = "Thank you for gathering these beautiful moths. Please accept this as thanks.", sourceObjectiveStatus = "unverified-source-field" }
