quests[96510] = { id = 96510, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elder Glowmite", sourceObjective = "Thank you for gathering these beautiful moths. Please accept this as thanks.", sourceObjectiveStatus = "unverified-source-field" }
quests[96522] = { id = 96522, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oh Captain, Die Captain!" }
quests[96523] = { id = 96523, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Living Legend", description = "These soldiers--dey are too young to remember the time before de loa gave us their help. So de loa can't come here. So? \n\nLet me tell a legend dat takes place before the loa helped our kind. Maybe you heard of it? Or maybe you want to see it for yourself...", sourceObjective = "Speak to Kehiah to begin the tale.", progress = "There's a lesson to be learned.", completion = "Look at you! No longer a champion, just a simple troll villager. Let's begin de story now that you're settled.", sourceObjectiveStatus = "unverified-source-field" }
quests[96525] = { id = 96525, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Out of Our Depth", description = "This is more than I'm prepared to deal with. \n\nI'll open a portal back to the Sanctum.\n\nI'm going to wait for these blasted little snakelings to grow tired of me before following you through. Do put in a good word for me, please.", sourceObjective = "Return to Astalor Bloodsworn in Silvermoon.", progress = "Of course there are ghosts.", completion = "You reek of fear and desperation.\n\nFascinating.", sourceObjectiveStatus = "unverified-source-field" }
quests[96528] = { id = 96528, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Anguish from Beyond", sourceObjective = "Explore the cursed tomb for Sanctum Attendant Ethrandil.", progress = "After you...", completion = "That's a lot of bones!", sourceObjectiveStatus = "unverified-source-field" }
quests[96532] = { id = 96532, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Attending the Attendant", description = "My methods might come across as cruel and unusual to some, but I do take to heart the well being of those who serve under me. \n\nMost of the time.\n\nAttendant Ethrandil has served our cause admirably. Please let him know he can return to me.\n\nThese floors have grown noticeably dirtier as of late...", sourceObjective = "Check in on Sanctum Attendant Ethrandil in the Coiled Isle.", completion = "You're alive! I'm alive! \n\nStill.", sourceObjectiveStatus = "unverified-source-field" }
quests[96534] = { id = 96534, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preparing for Threats", description = "My brother has always been the creative one, his hands busy on some intricate side project or some device he's working on. \n\nHis enthusiasm will benefit this operation greatly, especially when it comes to thwarting the threats we face on this world.\n\nSee what he's been working on and give one of his new experiments a trial run.\n\nI'm sure he'll be thrilled at the opportunity to contribute.", sourceObjective = "Purchase the Ethereal Bandages from Kifaan.", progress = "I am moderately confident his work will counter the occasional nuisance you might encounter on this world.", completion = "He's quite the little technomancer, isn't he?\n\nHe's come a long way since our days in the technomarkets back home. \n\nHis creations will go a long way in supporting your efforts here.\n\nWe are lucky to have him with us on this expedition. I am lucky to have him...\n\nIt has been a very long time since we've spent this much time together.", sourceObjectiveStatus = "unverified-source-field" }
quests[96539] = { id = 96539, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Last Resort", description = "Long, long ago, there was a village that suffered from a great drought. De crops wouldn't grow, and the land dried up. De whole village was starving! The villagers came to one troll--Jeytha--to ask her a favor. \n\nIn dis story, you are Jeytha--now go see what those hungry villagers want!", sourceObjective = "Speak to the Hungry Villagers to see what they want.", completion = "She traveled as asked, but oh! What's dat in the road ahead?", sourceObjectiveStatus = "unverified-source-field" }
quests[96540] = { id = 96540, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strong Hands", description = "Jeytha came across a fox in de path, beset by lynx. And she was kind, and unafraid, and strong--so she decided to help that fox out. \n\nNow go tell those lynx to get outta here!", sourceObjective = "Shoo the lynx away from the Sly Fox.", completion = "Well now! Dat fox seems to be more than just an ordinary fox, hm?", sourceObjectiveStatus = "unverified-source-field" }
quests[96541] = { id = 96541, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strong Mind", description = "That sly old fox wasn't just any fox! He spoke, and he ran, and he waited for Jeytha to meet him. Now what did he want with Jeytha? \n\nYou should talk to him and find out!", sourceObjective = "See what the Sly Fox wants.", completion = "Look at dat--right back where she started, and everyone's alive! Jeytha was as clever as she was strong!", sourceObjectiveStatus = "unverified-source-field" }
quests[96542] = { id = 96542, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Second to Last Resort", description = "Jeytha is smarter than that old fox. Watch what she says!", sourceObjective = "Ask the fox for your second boon.", sourceObjectiveStatus = "unverified-source-field" }
quests[96543] = { id = 96543, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Root of Survival", description = "Now dat she was back where she started, Jeytha knew she couldn't make that journey. But what of de starving villagers? How would they survive?\n\nJeytha had a few ideas... if the villagers would listen to her. Go see what she has to say!", sourceObjective = "Collect Withered Roots and Critter Meat for the village.", progress = "Please, Jeytha! Do not let our village starve!", completion = "It isn't much, but we can surely survive on dis. Thank you for your wisdom, Jeytha!", sourceObjectiveStatus = "unverified-source-field" }
quests[96544] = { id = 96544, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bravely Burning", description = "Years passed, and she didn't use dat third boon. One year, a flight of angry dragonhawks set their eyes--and flames--on de village. Her son was trapped, their home on fire! \n\n\"I could use my boon,\" thought Jeytha, \"But why use my boon, when I can use my strength?\"\n\nGo show those dragonhawks your strength, and save dat boy!", sourceObjective = "Kill 7 Enraged Dragonhawks and save Teho.", progress = "Oh, those fiery pests!", completion = "Phew! All in a day's work for Jeytha--and she still had dat third boon!", sourceObjectiveStatus = "unverified-source-field" }
quests[96545] = { id = 96545, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strong Voice", description = "The years passed, and still Jeytha did not use dat third boon. One year, a group of raiders arrived at de village, looking to steal everything dey had. \n\n\"I could use dat third boon,\" Jeytha thought, \"But why use dat boon when I can use my voice?\"\n\nGo talk those raiders down--and if dey don't listen, use your strength and change their minds!", sourceObjective = "Talk down 10 Angry Raiders.", progress = "Those raiders are gonna listen one way or another!", completion = "Jeytha was wise, and spoke true--and her voice soothed those raiders where blows would not.", sourceObjectiveStatus = "unverified-source-field" }
quests[96546] = { id = 96546, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strong Heart", description = "The years passed, and Jeytha felt her time coming. She'd lived a long life, full of struggles but still happy. But as Jeytha reached the end of her days, dat sly old fox appeared. \n\n\"Wait!\" he said. \"You can't go yet!\"\n\nNow what does that fox want? Go talk to him and find out!", sourceObjective = "Speak to the fox to see what he requires.", completion = "The sly fox ran off, grateful for Jeytha's boon. And Jeytha left her old bones a little after that--quieter, but just as content.", sourceObjectiveStatus = "unverified-source-field" }
quests[96547] = { id = 96547, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weaken Their Forces" }
quests[96548] = { id = 96548, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "High Spore" }
quests[96557] = { id = 96557, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flying Debris" }
quests[96567] = { id = 96567, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Data Decryption Disaster", description = "To understand the Hal'hadar's intentions with this world, we will need to secure information.\n\nKnowing how they operate, they've restricted their data consoles with security measures in place.\n\n<Y'mera smiles as she hands you a rune-carved crystal.>\n\nThis decrypter will automatically navigate their security. If you choose, you can engage the manual option to hasten the protocol.\n\nJust remember to ignore any security warnings. My device can and will bypass it.", sourceObjective = "Recover 3 Decrypted Data Records from the Hal'hadar Data Collators.", progress = "In the past, the Hal'hadar never stayed in one location for long, leaving whatever world they scavenged from just as quickly as they arrived.\n\nFor whatever reason, their intent with this world appears to be different.", completion = "One moment, there is much to glean from this data...\n\n<Y'mera murmurs under her breath as she works.>\n\nInteresting. They found a tomb of some kind under the swamp and...\n\nOh, what's this? Intercepted transcripts!\n\nIt seems Leth'ir's attacks on Azeroth were unsanctioned. Hal'hadar leadership is not pleased.\n\nThis information is most useful, {name}.\n\nGood work.", sourceObjectiveStatus = "unverified-source-field" }
quests[96568] = { id = 96568, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hal'hadon't You Dare!", description = "Y'mera's plan to intercept their data consoles will no doubt trigger heightened security protocols.\n\nNormally, no-contact reconnaissance would be advised in this situation, but I think sowing chaos will be more beneficial.\n\nThe Hal'hadar won't be aware of their stolen data if their entire manaforge is under attack.\n\nDispatch any Hal'hadar agents you find.", sourceObjective = "Kill 10 Hal'hadar at Manaforge: Arcvein.", completion = "For every Hal'hadar slain, paranoia grows like a sickness through their ranks.\n\nWhen distrust and fear is all that remains, their structure weakens and their operation falls.\n\nMy scouts will take advantage of the chaos you have created.\n\nGood work, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[96569] = { id = 96569, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Conductive Crystals", description = "<The glowing rune-marked crystal atop the Hal'hadar's device seems to be siphoning arcane spores out of the air.\n\nAlthough you're not quite sure what the device is, you get the feeling the crystal isn't quite ethereal in origin.\n\nY'mera would definitely be interested in examining some of these crystals.>", sourceObjective = "Collect 6 Energized Crystal Conductors from around Manaforge: Arcvein.", progress = "Yes, friend? What is it?", completion = "How fascinating!\n\nMy understanding of draenic might be a bit rusty but I believe these markings along the crystals matrices suggest they are used as a type of self-powered battery!\n\nIt seems the Hal'hadar are leveraging new ways to siphon arcane energy from this world!\n\nBut where did they get these crystals, I wonder?\n\nCurious find!", sourceObjectiveStatus = "unverified-source-field" }
quests[96570] = { id = 96570, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Technological Transference", description = "The Hal'hadar are notorious for looting and stealing technology from any world they descend upon.\n\nThanks to the intel you helped retrieve, we know they are using the manaforge east of us to experiment on whatever salvage they found.\n\nTake this translocator with you and mark anything that doesn't resemble ethereal technology.\n\nI will transport it back here for further study.", sourceObjective = "Use the Lightveil Translocator to recover stolen technology from the Hal'hadar.", completion = "I expected they found Legion or maybe Lightforged technology, but not draenei!\n\nThe vigilant appears to be severely damaged... its construct core entirely removed.\n\nAnd the defense crystal is shattered beyond repair.\n\nDid they find this here on Naigtal? Why bring it here otherwise?\n\nThere must be more to this. I will delve deeper into the data you found.", sourceObjectiveStatus = "unverified-source-field" }
quests[96571] = { id = 96571, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Node Knows", description = "The manaforge to the east serves as both a research site and military compound, making it a valuable target.\n\nMuch of their research, including holoprint schematics, lays around the forge.\n\nThe Hal'hadar stationed here also carry nodes containing experimental and logistical data.\n\nTake advantage of this accessible intel and bring back what you can find.", sourceObjective = "Recover Logistical Intel from the ethereals at the Eastern Manaforge.", progress = "Sometimes effective reconnaissance requires careful planning and stealth. Other times, sudden ambushes and unleashed chaos are more effective.\n\nI would know. I wrote the Lightveil Manifest, after all.", completion = "<Tala'saan's brow furrows in disbelief as he examines the holoprints.>\n\nThe crypt they found was built by... draenei?\n\nThis explains where the ethereals got the crystal conductors you found.\n\nBut how does it relate to this \"Nullframe\" they are building?\n\nOur warframes aren't exactly compatible with standard crystal technology.\n\nPerhaps Y'mera will find the answers in these data-nodes.", sourceObjectiveStatus = "unverified-source-field" }
quests[96572] = { id = 96572, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Malfunctioning Nullframe", description = "<From the runic communicator, you see a projection of a winged mechanical suit piloted by an ethereal. A voice emits from the device:\n\n\"Nullframe Soul-Fuse unsuccessful. Deployment from the Nexus Port halted. Troubleshooting in progress.\"\n\nWhatever weapon the Hal'hadar created seems to be malfunctioning at the Transit Hub.\n\nIntercepting and translocating the weapon back to Y'mera would deprive the ethereals of another weapon.>", sourceObjective = "Use Y'mera's Translocator to intercept the Nullframe at the Transit Hub.", progress = "What have you found, {name}?", completion = "The state of this Nullframe is gravely concerning.\n\nWith the judgment core torn from its mainframe, there is no way to control the mech...\n\nThe Hal'hadar must be trying another means of piloting their twisted creation.\n\nVeraan and Kifaan are more familiar with ethereal technomancy.\n\nWhile they take a closer look, I will scour what data banks we've gathered.", sourceObjectiveStatus = "unverified-source-field" }
quests[96573] = { id = 96573, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Soul Lattice Revealed", description = "It took some work, but we've cracked their ciphers.\n\nThe Hal'hadar seek to power their Nullframes using draenei vigilant technology.\n\nThe \"Soul Lattice\" is a heart for the Nullframe using a vigilant's core.\n\nWith it, they can bind their unwrapped energy into the core and wear the frame like armor.\n\nThe Hal'hadar must not succeed in finishing this prototype.\n\nY'mera is planning the next move. Speak with her.", sourceObjective = "Speak with Y'mera about their plan.", progress = "Riftblade Maella agrees that the Hal'hadar in the crypt must be stopped.\n\nIt may not be the crux of their operation here on Naigtal, but it is not a threat we can ignore.", completion = "Y'mera's data suggests the tomb is heavily congested with Hal'hadar.\n\nWhile the rest of our forces rout the ethereals around the island, we'll opt for a more subtle approach.\n\nAllari the Souleater has been monitoring the north coast and will join our infiltration into the crypt.\n\nThe irony of her title in such a place is not lost on me.", sourceObjectiveStatus = "unverified-source-field" }
quests[96574] = { id = 96574, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cryptside Rendezvous", description = "The tomb is called Vilaldoun. It means \"island of the restful.\" Its entrance lies on the northern coast.\n\nWe know the Hal'hadar have established an extraction site outside the crypt, harvesting the local flora there to fuel their research.\n\nAs you approach, you will be met with heavy resistance.\n\nCut a path through their ranks while we establish a footing inside and meet us within.", sourceObjective = "Slay 12 Hal'hadar on the Extraction Shores.", progress = "For a bunch of scavengers, these ethereals are far more provocative than I expected. It will make killing them all the more satisfying.", completion = "I won't say I wasn't half tempted to join you up there, but someone's got to watch Y'mera's back.\n\nTala'saan's gone ahead to find the architect behind this operation.\n\nWe've managed to secure our position here in the stairwell, blocking any Hal'hadar who try to follow.\n\nThat leaves you to cut through this defiled place.", sourceObjectiveStatus = "unverified-source-field" }
quests[96575] = { id = 96575, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cages of the Soul", description = "Without the tomb's defenses, the souls of the dead were easy targets for the Hal'hadar.\n\nThe ethereals intend to use the spirits to fuel the Soul Lattices for the Nullframe.\n\nWe must not let that happen.\n\nTake my scepter and use it to repair the defense wards and shatter the energy cages binding the dead.\n\nOnce you've finished, regroup with Tala'saan in the lower chambers.", sourceObjective = "Free 15 Draenei Spirits from Ethereal Cages.", progress = "We cannot allow the spirits of our dead kin to be harvested by these monsters.", completion = "I cannot help but wonder how long have these draenei been buried here...\n\nHow many cycles have gone by since this small corner of draenei civilization faded.\n\nWas it the Legion who awoke them into unrest years ago? Or did the Hal'hadar's plundering disturb them?\n\nAll that matters now is that they return to their rest.\n\nThe wards will ensure they are not disturbed again.", sourceObjectiveStatus = "unverified-source-field" }
quests[96576] = { id = 96576, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mementos of the Dead", description = "Defiling tombs... harnessing innocent souls as fuel...\n\nThe Hal'hadar are no better than demons.\n\nIf left unchecked, the ethereals will pilfer every grave and altar down here.\n\nI may bear the title of \"Souleater,\" but it doesn't mean I can't honor the dead in this forgotten place.\n\nRecover the tributes the ethereals have stolen. Bring them to Tala'saan in the lower chamber.", sourceObjective = "Recover 30 Forgotten Memorial Tributes.", progress = "<Tala'saan appears quite calm, his armor flecked with arcane smatterings of the ethereals he slew.>\n\nWhat did you find?", completion = "<Tala'saan is silent for a moment as he examines the mementos you recovered.>\n\nAllari asked you to recover these?\n\nAnd here I was assuming her investment in our mission was simply an excuse to slaughter ethereals.\n\nThank you, {name}.\n\nI will see to it these mementos are laid to rest in a more secure location.", sourceObjectiveStatus = "unverified-source-field" }
quests[96577] = { id = 96577, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Soul Architect", description = "The architect leading their operation has found a single vigilant with an intact construct core.\n\nThe other vigilants in this chamber appear to be depleted.\n\nIf she succeeds in creating the Soul Lattice, the Hal'hadar will possess the means to turn our warframes into new armored bodies for their soldiers.\n\nWe must stop her now and recover the Soul Lattice prototype.", sourceObjective = "Defeat the Null Architect and recover the Soul Lattice Prototype.", progress = "If the Hal'hadar succeed in forging a Soul Lattice, then they may possess the means to use our technology against us.", completion = "It is done and yet...\n\n<Tala'saan trails off for a moment as he thinks, his brow furrowed.>\n\nThe Soul Lattice may be broken, but there is something we are still missing.\n\nThe vigilants she took were vacant, their cores depleted of the souls that inhabited them.\n\nWhat \"true key\" did she seek if not their construct cores? Why would she take empty husks?", sourceObjectiveStatus = "unverified-source-field" }
quests[96578] = { id = 96578, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cryptic Departure", description = "Although she escaped, we have denied the architect her prototype... for now.\n\nThis Soul Lattice is fractured, but the core within still hums with a faint energy.\n\nPerhaps this vigilant's soul yet remains...\n\nIf we hurry, perhaps Veraan and her brother can help stabilize the damage to preserve it.\n\nI will regroup with Y'mera and Allari and meet you back at camp.", sourceObjective = "Return to the Umbral Base Camp.", completion = "<Veraan examines the Soul Lattice.>\n\nI am no expert on the Hal'hadar's work but even I can tell the damage here is significant.\n\nAt this rate, the vigilant core won't remain intact for much longer.\n\nIf Kifaan and I can unravel the lattice carefully, maybe we can pry the core loose.\n\nIf we're extra careful, perhaps we can preserve the lattice as well.\n\nI make no promises, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[96588] = { id = 96588, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prey: Venom Ambush" }
