quests[96612] = { id = 96612, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ancient Curiosity: Combat", description = "<You hold the curio and discover a shimmering glow emanating from it. This looks important.>", sourceObjective = "Use and equip a Combat Curio to your delve companion.", sourceObjectiveStatus = "unverified-source-field" }
quests[96614] = { id = 96614, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forged Through Fire", sourceObjective = "It is said the blessings of a phoenix long-forgotten seep through every swing of the hammer and bellow of flames at this forge.\n\nThat is why any who are serious about their craft come from all over to forge their creations here at this spot. Perhaps though, all that power is just superstition. A way for the Sunstrider dynasty to give power to the powerless. Yet again, perhaps it is not.\n\nGive it a try, won't you?", sourceObjectiveStatus = "unverified-source-field" }
quests[96615] = { id = 96615, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ancient Curiosity: Utility", description = "<You hold the curio and discover a shimmering glow emanating from it. This looks important.>", sourceObjective = "Use and equip a Utility Curio to your delve companion.", sourceObjectiveStatus = "unverified-source-field" }
