quests[96625] = { id = 96625, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spectral Gladiators" }
quests[96633] = { id = 96633, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Equipment Seminar", description = "Welcome back, {name}! I've continued my collaboration with the artisans here in Silvermoon. Their techniques have only grown more refined. Infusing equipment with the essence of the dawn is no longer just theory, it's becoming an art form.\n\nI'm eager to resume our work together. Bring me another piece of Adventurer equipment, and we'll see how these improved methods hold up in practice.\n\nPlenty of people are always in need of a capable hand. Help them, and they'll reward you accordingly.", sourceObjective = "Obtain a piece of Adventurer track gear, then return to Vaskarn in Silvermoon.", progress = "If you're having trouble finding a piece of Adventurer equipment, I hear that Amani expedition to that forbidden island could really use a hand. They might be willing to reward you with equipment for your aid.", completion = "With my improved methods, I can make this far better. All we need left are the reagents.", sourceObjectiveStatus = "unverified-source-field" }
quests[96635] = { id = 96635, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Upgrade Practicum", description = "Cuzolth and I have pushed our craft further than ever, allowing us to imbue your gear with greater power.\n\nTo unlock its full potential, we'll need Mistcrests. They're drawn from trials of all kinds--greater dangers yield stronger crests, though even Adventurer Mistcrests carry a spark of that power.\n\nBring me fifty Adventurer Mistcrests, {name}. Let's see what your equipment is truly capable of.", sourceObjective = "Acquire 50 Adventurer Mistcrests by defeating unique creatures, completing world activities, or by looting caches. Speak to Cuzolth to upgrade an Adventurer track item using those crests, then return to Vaskarn in Silvermoon.", progress = "If Adventurer Mistcrests prove elusive, turn your gaze to the hidden corners of the forbidden island that the Amani are currently exploring. Their efforts may yield exactly the Mistcrests we seek.", completion = "Fantastic! Just what I was hoping for.\n\nYou're growing stronger with each step... which is, of course, my primary concern. My research simply benefits alongside it. Naturally.", sourceObjectiveStatus = "unverified-source-field" }
quests[96637] = { id = 96637, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Veteran Symposium", description = "There is a lot more power where that came from!\n\nUpgrades scale with strength. Higher quality items can reach higher heights of power. For this step, I'll need Veteran equipment along with some Veteran Mistcrests.\n\nOnce you bring them, Cuzolth and I can continue making the enhancements.", sourceObjective = "Obtain a piece of Veteran track gear and 15 Veteran Mistcrests. Speak to Cuzolth to upgrade a Veteran track item using those crests, then return to Vaskarn in Silvermoon.", progress = "Completing a Heroic dungeon or a challenging weekly activity with the Amani expedition should grant you the Veteran equipment you seek. Taking part in their efforts should also get us those Veteran Mistcrests!", completion = "Good work, you're a natural at this!\n\nThe process always stays the same: bring us the item along with the appropriate crests, and Cuzolth will handle the upgrade.", sourceObjectiveStatus = "unverified-source-field" }
quests[96639] = { id = 96639, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Patrolling the Temple", description = "No sense standin' around. You've got a strong back and sharp eyes--best put them to use. We can't afford to let de serpents gain a single inch. \n\nPatrol de temple. You see someone who needs help? You help them. You find someone beyond saving? Make sure de fiends dat hurt them pay.", sourceObjective = "Complete Temple Patrols within the Vaults of Atal'Utek.", completion = "Fine work. If I had a hundred more paladins like you, we'd have de temple cleared out in a week.", sourceObjectiveStatus = "unverified-source-field" }
quests[96640] = { id = 96640, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bounty of the Cursed", sourceObjective = "Gather Forgotten Relics from Soulcoiler Caches and Troves.", progress = "What have you found?", completion = "We'll use de Soulcoilers' own works to purge dem.", sourceObjectiveStatus = "unverified-source-field" }
quests[96641] = { id = 96641, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Relentless Strikes", description = "Some say de forces of Ula'tek are endless--dat we can never kill them all.\n\n<Socho grins.>\n\nBut I like a challenge. How 'bout you? Strike de enemy hard, and we'll see how endless dey are.", sourceObjective = "Complete Temple Strikes in the Vaults of Atal'Utek.", progress = "Take de fight to de enemy. We won't give dem a second of rest.", completion = "Dis isn't your first war, is it? De serpents gonna learn to fear you before dis is done.", sourceObjectiveStatus = "unverified-source-field" }
quests[96642] = { id = 96642, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Decisive Incursions", description = "De strikes are de first step. We cannot let de enemy recover. First we batter them, soften 'em up. Then, we hit dem hard and fast with everything we've got. \n\nWe don't have de forces for a longer battle. When de time comes for de incursion, you'd best be ready.\n\nGather your allies. De enemy is mighty.", sourceObjective = "Successfully complete a Temple Incursion event in the Vaults of Atal'Utek.", completion = "Now dat was a battle worthy of de old songs! I can see why Zul'jarra likes you.", sourceObjectiveStatus = "unverified-source-field" }
quests[96643] = { id = 96643, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "From Whence it Came", description = "Can you feel it? Old things lurk in de temple, just waitin' to rise once again. Dey are drawn by the sounds of battle, eager to visit their violence upon you. Find one of these ancient foes and ensure it does not rise again.", sourceObjective = "Defeat an ancient foe in the Vaults of Atal'Utek. Ancient foes will rise upon the completion of an incursion.", progress = "Can you feel it? De violence just waitin' to spill over?", completion = "Keep your blades sharp. De temple never sleeps for long.", sourceObjectiveStatus = "unverified-source-field" }
quests[96644] = { id = 96644, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Essence of Malice", description = "I'm in need of venom, pure and potent. De venom dat wells up through de ground is too diluted--fouled with other things. You need to find a font of de profane stuff.\n\nSearch de depths of de vaults. Dat's where de true venom will be found.", sourceObjective = "Gather Malefic Venom from the depths of the Vaults of Atal'Utek.", progress = "Well, do you have it?", completion = "<Er'inye takes the vial, a wicked smile playing across her face.>\n\nOh, you've done well. Dis is even more than I was hopin' for.", sourceObjectiveStatus = "unverified-source-field" }
quests[96649] = { id = 96649, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mistcrest Capstone", description = "Crests aren't fixed in form, you can transmute them between tiers.\n\nIf you're holding crests beyond what your current gear can use, I can refine them into lower tiers. And once your equipment advances, we can reverse the process and elevate lesser crests into greater ones.\n\nLet's start with a simple exercise. Bring me those Veteran Mistcrests, and I'll convert them into Adventurer Mistcrests.", sourceObjective = "Bring 10 Veteran Mistcrests to Vaskarn in Silvermoon, then trade them for a Bundle of Adventurer Mistcrests.", progress = "If you lose those Veteran Mistcrests, you can find more from powerful creatures near the Amani Expedition. I've heard there's quite a variety of them!", completion = "Amazing work!\n\nRemember: transmutation upward is only possible once a crest has outlived its usefulness to your gear, and it comes at a considerable cost.\n\nThank you for your assistance, {name}.", sourceObjectiveStatus = "unverified-source-field" }
