quests[96699] = { id = 96699, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mushroom Top Tendril Sling" }
quests[96703] = { id = 96703, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Veterans of the Great Dark", description = "When the Hal'hadar attacked, we quickly learned about their history with the Army of the Light.\n\nCommander Tala'saan has been providing us information on these ethereals. His soldiers stand ready to join our cause.\n\nI've requested their expertise in establishing a forward camp for our mission.\n\nAid them in their preparations and inform the commander we mobilize soon.", sourceObjective = "Recruit Commander Tala'saan and the Lightforged for Maella's expedition.", progress = "I'll admit, after the events of the Voidspire, I remain cautious about relying on allies so... dedicated to the Light.\n\nBut personal reservations aside, I cannot deny their expertise in fighting the Void and the Hal'hadar.", completion = "Tala'saan did forewarn me only a few Lightforged could be spared. The attack on the Voidspire left their forces decimated.\n\nMany wounded, many more slain or missing.\n\nAny support we can muster from the Army of the Light will go a long way in this operation.", sourceObjectiveStatus = "unverified-source-field" }
quests[96708] = { id = 96708, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Voidstorm and Beyond!", description = "It may not seem like many, but the allies we've secured will have to be enough.\n\nIt's time we move out.\n\nOur forces are gathering at the Howling Ridge. The energies of the Voidstorm will allow us to open the way to these worlds.\n\nI will meet you there. There is something here I still require for our mission.", sourceObjective = "Meet Maella and the Strike Team at the Howling Ridge in the Voidstorm.", progress = "Our enemies will not be expecting our assault. We must strike fast and true.", completion = "This may be an unusual coalition of allies, but each one leverages expertise we can use against our enemies.\n\nEven Decimus cannot deny that.\n\nI've secured the last component we need, the Cynosure of Twilight, to open the rift to where these ethereals and void forces operate from.\n\nAre you ready, {name}?", sourceObjectiveStatus = "unverified-source-field" }
quests[96709] = { id = 96709, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Nexus-Captain (Heroic)", description = "The Hal'hadar may not know we are here yet, but they still hold the advantage.\n\nNexus-Captain Leth'ir and his associate, Mertei, are just over this ridge and surrounded by a small army.\n\nIf you can rally enough allies and catch their leaders off guard, we'll deal a devastating blow before they know what hits them.\n\nProceed with caution, {name}, and make sure you are not alone.", sourceObjective = "Defeat Nexus-Captain Leth'ir in Heroic World Tier.", sourceObjectiveStatus = "unverified-source-field" }
quests[96711] = { id = 96711, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Imperator Pertinax (Heroic)", description = "Like all domanaar, Imperator Pertinax sees himself only as a predator and never the prey.\n\nUnfortunately, our prey is well-guarded in his Void Acropolis.\n\nIf you manage to gather enough allies and catch the imperator off guard, we'll deal a crushing blow to our enemies.\n\nMove swiftly and cautiously, {name}, and ensure you have backup before engaging Pertinax.", sourceObjective = "Defeat Imperator Pertinax in Heroic World Tier.", sourceObjectiveStatus = "unverified-source-field" }
quests[96713] = { id = 96713, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Showdown on Val", description = "Our enemy's hold on Val may be strong, but it is not unbreakable.\n\nFor every monstrosity we cut down, we deny them another soldier to use against our world.\n\nVenture out into the frozen landscape and lay waste to their strongholds.\n\nShow them no mercy, {name}.", sourceObjective = "Disrupt the domanaar forces on Val by completing World Quests, slaying rare creatures, completing events, and looting treasures.", progress = "Something to report?", completion = "By disrupting the domanaar's operation, you divert their attention away from Azeroth.\n\nYou have my thanks, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[96714] = { id = 96714, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Showdown on Val (Heroic)", description = "Our enemy's hold on Val may be strong, but it is not unbreakable.\n\nFor every monstrosity we cut down, we deny them another soldier to use against our world.\n\nVenture out into the frozen landscape and lay waste to their strongholds.\n\nShow them no mercy, {name}.", sourceObjective = "Disrupt the domanaar forces on Heroic Tier Val by completing World Quests, slaying rare creatures, completing events, and looting treasures.", progress = "Something to report?", completion = "By disrupting the domanaar's operation, you divert their attention away from Azeroth.\n\nYou have my thanks, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[96716] = { id = 96716, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Showdown on Val", description = "Our enemy's hold on Val may be strong, but it is not unbreakable.\n\nFor every monstrosity we cut down, we deny them another soldier to use against our world.\n\nVenture out into the frozen landscape and lay waste to their strongholds.\n\nShow them no mercy, {name}.", sourceObjective = "Disrupt the domanaar forces on Val by completing World Quests, slaying rare creatures, completing events, and looting treasures.", completion = "By disrupting the domanaar's operation, you divert their attention away from Azeroth.\n\nYou have my thanks, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[96717] = { id = 96717, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Showdown on Naigtal", description = "Now this is quite a strange world, isn't it?\n\nThe Hal'hadar must have found something of note.\n\nThe stench of forges indicates they are plundering the riches and resources this remote rock has to offer.\n\nIf you can disrupt the operations here, you can buy your precious world a moment of respite.\n\nDo what you do best, my little monster.", sourceObjective = "Disrupt the Hal'hadar on Naigtal by completing World Quests, slaying rare creatures, completing events, and looting treasures.", progress = "I trust you bring tales of wanton destruction to share with me?", completion = "My, you have been quite the busy engine of chaos, haven't you?\n\nI always delight in your dramatic tales of... heroism. Take a moment to bask in the glow of the destruction you created.\n\nDon't wander too far now. We are not quite done with this little fungal world.", sourceObjectiveStatus = "unverified-source-field" }
quests[96718] = { id = 96718, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Showdown on Naigtal (Heroic)", description = "Now this is quite a strange world, isn't it?\n\nThe Hal'hadar must have found something of note.\n\nThe stench of forges indicates they are plundering the riches and resources this remote rock has to offer.\n\nIf you can disrupt the operations here, you can buy your precious world a moment of respite.\n\nDo what you do best, my little monster.", sourceObjective = "Disrupt the Hal'hadar on Naigtal by completing World Quests, slaying rare creatures, completing events, and looting treasures.", completion = "My, you have been quite the busy engine of chaos, haven't you?\n\nI always delight in your dramatic tales of... heroism. Take a moment to bask in the glow of the destruction you created.\n\nDon't wander too far now. We are not quite done with this little fungal world.", sourceObjectiveStatus = "unverified-source-field" }
quests[96720] = { id = 96720, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Showdown on Naigtal", description = "Now this is quite a strange world, isn't it?\n\nThe Hal'hadar must have found something of note.\n\nThe stench of forges indicates they are plundering the riches and resources this remote rock has to offer.\n\nIf you can disrupt the operations here, you can buy your precious world a moment of respite.\n\nDo what you do best, my little monster.", sourceObjective = "Disrupt the Hal'hadar on Naigtal by completing World Quests, slaying rare creatures, completing events, and looting treasures.", progress = "I trust you bring tales of wanton destruction to share with me?", completion = "My, you have been quite the busy engine of chaos, haven't you?\n\nI always delight in your dramatic tales of... heroism. Take a moment to bask in the glow of the destruction you created.\n\nDon't wander too far now. We are not quite done with this little fungal world.", sourceObjectiveStatus = "unverified-source-field" }
quests[96725] = { id = 96725, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sparks of War: Val", description = "The mysterious world of Val has been made accessible to us with a host of new creatures present.\n\nGo and see what you can find out about them.", sourceObjective = "Collect 100 Otherworldly Sparks of War in Val, while in War Mode.", progress = "There's still more to do.", completion = "That provides some answers, many thanks.", sourceObjectiveStatus = "unverified-source-field" }
quests[96726] = { id = 96726, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sparks of War: Naigtal", description = "The mysterious world of Naigtal has been made accessible to us with a host of new creatures present.\n\nGo and see what you can find out about this world and what the ethereals are up to.", sourceObjective = "Collect 100 Otherworldly Sparks of War in Naigtal, while in War Mode.", progress = "There's still more to do.", completion = "That provides some answers, many thanks.", sourceObjectiveStatus = "unverified-source-field" }
quests[96727] = { id = 96727, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Midnight: Offworld Showdowns", description = "Our effort to thwart the Void Assaults in Eversong and Zul'Aman have seen much success, but if we do not find a way to stop our aggressors from coming to our lands, they will bleed us until we can no longer stand.\n\nRiftblade Maella has recently discovered the location of two of our enemies' bases. She seeks to take the fight to them. Will you aid her strike team?\n\nYour efforts will not go unnoticed in these dark times!", sourceObjective = "Disrupt either the enemy base on Val or Naigtal in Midnight.", completion = "Thank you, {class}. You have taken the fight to the doorstep of our enemies. With your efforts, we hope to reduce one enemy who threatens our world.", sourceObjectiveStatus = "unverified-source-field" }
quests[96728] = { id = 96728, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ritual Site Studies: Week 1 of 3", description = "After you reported thinning out their ranks I got to thinking. \n\nWhat do they use to recruit members? Are they just as fanatical as their leaders?\n\nI wonder if we can break their will to fight by destroying a greater number of their ranks. I fear it will take more than one example to know for sure.", sourceObjective = "Disrupt two Tier 6 Ritual Sites while the Reinforcements challenge is active.", completion = "The second ritual was just as protected as the first?\n\nWell, I cannot say I am surprised. Our own people wouldn't be easily deterred and well their leaders are very persuasive. We also have set back the ambitions of these groups again and again.\n\nI will study what you have brought me and have a new assignment for you soon.", sourceObjectiveStatus = "unverified-source-field" }
quests[96729] = { id = 96729, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ritual Site Studies: Week 2 of 3", description = "I have your next assignment, {race}. I need you to study the resilience of these malevolent boons and their dark obelisks.\n\nThey focus magic so well and the variety of boons is interesting. I need more data though.\n\nWhen you disrupt the next ritual site I need you to do so with these malevolent boons present.", sourceObjective = "Disrupt two Tier 6 Ritual Sites while the Malevolent Boons challenge is active.", progress = "What did you discover?", completion = "This time consistency is in our favor. Well my favor at least. \n\nYour report fills in a few gaps I had in understanding how the obelisks interact and connect with their forces.\n\nThank you again, I will prepare a new lesson for you.", sourceObjectiveStatus = "unverified-source-field" }
quests[96730] = { id = 96730, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ritual Site Studies: Week 3 of 3", description = "I think I am on the brink of a big discovery. These latest rituals involve a magic I had not previously heard of in the form of powerful embers that use the energy of their own forces to bolster their leader.\n\nIf you disrupt these rituals and report your findings to me, I might be able to put this magic to use for us. Do not look at me that way. On my own demon minions of course. Did you think I meant troops like you?\n\nWe are much too early for trials like that. Report back with your findings!", sourceObjective = "Disrupt two Tier 6 Ritual Sites while the Embers challenge is active.", completion = "Hmm... your notes are not as detailed as I would like. I do wish you had left more of them active when you took on their leader...\n\nI guess that may have resulted in your death and loss of the data so I will make due. This is promising. \n\nOh, you are still here. Yes, I promised you a reward for helping me with this line of inquiry.\n\nI wonder, if we were to study these in specific combinations... well that is for another time.", sourceObjectiveStatus = "unverified-source-field" }
quests[96731] = { id = 96731, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Advanced Ritual Site Studies: Week 4 of 6", description = "I had an idea right after you left. \n\nWe have thinned out their ranks, we have also seen that they can summon additional reinforcements.\n\nI want to test the limits of their reserves.\n\nIf you take on this set of challenges, I promise you another key for the vault.", sourceObjective = "Disrupt two Tier 6 Ritual Sites while the Reinforcements and Magic Alarm Bells challenges are active.", completion = "This is starting to bear fruit. While they did maintain their troop numbers in your latest attempts to disrupt the ritual they slowed by just a few seconds on that last alarm portal.\n\n{race}, we just have to keep up the pressure. They will break soon I am sure. We must look into these obelisks next.", sourceObjectiveStatus = "unverified-source-field" }
quests[96732] = { id = 96732, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Advanced Ritual Site Studies: Week 5 of 6", description = "Now that we have tested their troop reserves, our focus will be the dark obelisks and these boons they give.\n\nThis requires close scrutiny and will surely entail you facing increased patrols while you explore the site. Not too difficult for someone like yourself.\n\nJust avoid them... or deal with them if you must.", sourceObjective = "Disrupt two Tier 6 Ritual Sites while the Malevolent Boons and Patrols challenges are active.", completion = "This is good, the dark obelisks are more resilient than I thought. You look surprised again. Of course this is good news I think I almost have learned enough to fashion something like them myself.\n\nNow, can't you see how much of a boon this would be? It's not always about denying or destroying the enemies assets. Often it is learning how to use their tools against them... or other threats.", sourceObjectiveStatus = "unverified-source-field" }
quests[96733] = { id = 96733, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Advanced Ritual Site Studies: Week 6 of 6", description = "Welcome back my star pupil. I have one last assignment for you and this one will be a challenge.\n\nThese embers that they use in these rituals. I have not had any success in replicating them or finding a way to counter them.\n\nI have one last idea I want you to try. You reported seeing magical manifestations of caster spirits. I have a theory that with these two challenges present there might be a way for them to cancel each other out.", sourceObjective = "Disrupt two Tier 6 Ritual Sites while the Embers and Manifestation challenges are active.", completion = "It did not work? Well that is disappointing. It was worth a chance, that is something you will learn if you continue to study rituals. Sometimes you just have to try things.\n\nAt times it will amount to nothing, other times it can let you summon a giant demon to smite your foes. I don't recommend the latter for you. It probably wouldn't go well for you or your foe.\n\nWell that is all I have need of from you. Take the key and my thanks!", sourceObjectiveStatus = "unverified-source-field" }
quests[96744] = { id = 96744, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bouncy Mushrooms", description = "Hello! Here's a trick to help you bounce on the purple mushrooms around here. You'll need it, because...\n\nI want some canopy specimens from the sporerays above us. Bounce up there, get some specimens, then come back down and I'll teach you how to ALWAYS bounce on those mushrooms.", sourceObjective = "Gather Canopy Specimens from creatures on and around the tops of giant mushrooms. Bring them to Kifaan in Naigtal Outpost.", progress = "I need those specimens. Bounce on the mushrooms and look for Sporerays.", completion = "Thank you. I'll put these to good use. Now you can jump on those mushrooms all the time.", sourceObjectiveStatus = "unverified-source-field" }
quests[96745] = { id = 96745, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aerospores", description = "Now, practice using aerospores. They're up there too if you know where to look. Use them to shoot through the air!\n\nYou'll need to bounce on mushrooms to get up to the spores and see them. Once you're up there, pass through some aerospores and find out what they do!", sourceObjective = "Pass through the spores floating above the giant mushrooms, then return to Kifaan.", completion = "Well done. You did the hard part, now let me tell you the trick to it.\n\n<He tells you the trick to using aerospores.>", sourceObjectiveStatus = "unverified-source-field" }
quests[96746] = { id = 96746, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sporefall: Rotmire", description = "Need help! End of Harandar! End of world!\n\nSpore Storm making something new for Grudge Pit, but too much. Too much! Can't control. Will break free! Destroy pit. Destroy us all!\n\nMust go to Sporefall, destroy Rotmire before they lose control!\n\nFor Harandar! For Azeroth! For Grudge Pit!", sourceObjective = "Enter Sporefall and defeat Rotmire.", completion = "You save us all. Fungaria! Harandar! World! Grudge Pit!\n\nBut world, mostly world.", sourceObjectiveStatus = "unverified-source-field" }
quests[96780] = { id = 96780, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Local Kafa Shop", sourceObjective = "Greetings, friend of the Grummles!\n\nI sell kafa in your neighborhood now. You buy local. \n\nCheck out my wares!", sourceObjectiveStatus = "unverified-source-field" }
quests[96794] = { id = 96794, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fury of the Dead", sourceObjective = "You will learn:", sourceObjectiveStatus = "unverified-source-field" }
quests[96801] = { id = 96801, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Calling All Combatants!", description = "<You read a nearby advertisement...>\n\nRun, don't walk!\n\nThe Artisan's Consortium has teamed up with local Silvermoon artisans in Falconwing Square to offer a new selection of heraldries and crafted equipment. These are certified for use in arenas and battlegrounds, guaranteed!\n\nHead on down and look for Mirvedon to receive your free sample today.\n\nAct now while supplies last! Terms and conditions apply.\n\n-Aisha", sourceObjective = "Follow up on the advertisement with Mirvedon at Falconwing Square in Silvermoon City.", completion = "<Mirvedon clears his throat.>\n\nTake these heraldries straight over to the Crafting Order station to get a custom piece. Anything you make with these will keep you safe while crossing swords in the battlegrounds. If you ever want more heraldries I've got what you need.\n\nFor a price this time, of course.", sourceObjectiveStatus = "unverified-source-field" }
quests[96808] = { id = 96808, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sparks of War: The Coiled Isle", description = "There's unknown danger out in the Coiled Isle.\n\nGet out there and clear things up!", sourceObjective = "Collect 100 Sparks of War in the Coiled Isle, while in War Mode.", progress = "Well, get on then!", completion = "Many thanks for clearing things out.", sourceObjectiveStatus = "unverified-source-field" }
quests[96809] = { id = 96809, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Exterior Manaforge Translocator", description = "Maneuvering through this spore-infested rock is quickly becoming a chore, I'm sure you would agree.\n\nThankfully, I've figured out a way to make use of the existing Manaforge Translocator network that was so thoughtfully built prior to our arrival.\n\nI can show you how to \"activate\" them for our use. You can start with the one we... translocated to camp.", sourceObjective = "Activate Manaforge Translocators across Naigtal.", progress = "Have the Manaforge Translocators been activated?", completion = "Superb! Now we'll be able to navigate swiftly and unseen.", sourceObjectiveStatus = "unverified-source-field" }
quests[96831] = { id = 96831, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magister's Summons", description = "Magister Umbric sends word that he and Rommath have a lead to further your empowerment of the Omnium Folio.", sourceObjective = "Seek out Umbric and Rommath in Magisters' Terrace.", completion = "Let us not waste time. We have much to talk about.", sourceObjectiveStatus = "unverified-source-field" }
quests[96845] = { id = 96845, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Grappler", description = "You have to try this Lightforge Hookshot! Here, take this loaner one. To learn the ropes, use it on some mushrooms and aerospores around here. Come back and I'll give you a Hookshot for keeps.", sourceObjective = "Use your Lightforge Hookshot on purple mushrooms and aerospores.", progress = "Get out there, {name}. Grapple onto those mushrooms and aerospores. And don't forget to have fun!", completion = "What did you think? Useful here, yes? Here's one for you to keep. Watch yourself out there!", sourceObjectiveStatus = "unverified-source-field" }
