quests[96936] = { id = 96936, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Accolades for the Umbral Contender", description = "{name}, you continue to impress me with your martial prowess!\n\nYou've done such an incredible job defeating the forces of evil. I've got something from my coffers that I'd love to give you.", sourceObjective = "Speak with Lindormi regarding your deeds in Mythic Keystone dungeons.", completion = "You're incredible, {name}!\n\nPlease have this saddle as a token of my appreciation.", sourceObjectiveStatus = "unverified-source-field" }
quests[96941] = { id = 96941, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Pertinent Punishment" }
