quests[96960] = { id = 96960, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Watering Hole", sourceObjective = "Hey there,\n\nThanks to your neighborhood's efforts, we were able to upgrade the bar. \n\nI've got a few new drinks available I think you'll really like.", sourceObjectiveStatus = "unverified-source-field" }
quests[96965] = { id = 96965, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sip N' Paint" }
quests[96995] = { id = 96995, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Turn Back the Surge", description = "De temple can no longer contain Ula'tek's wrath. De boldest of her brood are spilling out all over de isle! They'll destroy us all if we don't stem de tide of venom.\n\nFight dem wherever dey dare to show their ugly heads. Do not let dem get a foothold.", sourceObjective = "Defeat 3 Curse Surges.", progress = "We must survive.", completion = "Dat will keep them at bay... until the next surge, anyway.\n\n<Zela regards you grimly.>\n\nDon't let your guard down.", sourceObjectiveStatus = "unverified-source-field" }
quests[97016] = { id = 97016, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mixing Mysteries", description = "You think you've got some potent ingredients for my stew, eh? We'll see what de spirits think.\n\nShow me what you've brought and I'll throw it in de cauldron. De spirits will eat their fill, and if dey like it, you might get a reward.\n\nOr a punishment, if dey hate it. So choose wisely!", sourceObjective = "Bring three potent ingredients to Ofi the Sly.", completion = "<The spirits have received your offering and grant you one in return.\n\nAre they pleased? Are they angry? Are they feeling a little mischievous?\n\nYou will know soon enough.>", sourceObjectiveStatus = "unverified-source-field" }
quests[97026] = { id = 97026, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Esoteric Ingredients", description = "<These mundane materials have acquired a queer shine to them, almost as if you are noticing a power latent in them that you could not perceive before.\n\nMust have something to do with all that corrosion you've been consuming.\n\nYou aren't sure how to unlock that latent power, but perhaps there is someone more familiar with the esoteric magic of the isle that could help.>", sourceObjective = "Speak with Ofi the Sly at her hut in the swamp.", completion = "Oh yes. Dis is a big cauldron indeed.\n\nI know exactly what to do with dis.", sourceObjectiveStatus = "unverified-source-field" }
quests[97031] = { id = 97031, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vilaldoun Valediction", description = "<A brief glint sparkling in the shadows catches your eye.\n\nAs you pick up the object, the gem in its center flickers briefly, strange alien runes flashing across its surface.\n\nFor a moment, you see a flickering recorded projection of a male draenei mouthing silent words.\n\nY'mera will definitely be interested in this object.>", sourceObjective = "Deliver the Hologem to Archmage Y'mera in the Umbral Base Camp.", completion = "You found this in the tomb?\n\nThis is a hologem--a draenei tool used for communication and storing information.\n\nIt looks to be nearly depleted of its power. The ethereals must've thought this to be some mere trinket.\n\nI will see if I can energize it and access the information within.\n\nPerhaps it will reveal more about those buried within Vilaldoun.", sourceObjectiveStatus = "unverified-source-field" }
quests[97034] = { id = 97034, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vanquish the Warmonger", description = "Poor Impotus doesn't seem to believe we can seize control from his nefarious kin. He's tragically unimaginative.\n\nWe'll just need to show him an example of our combined strength. Slay that brute of a newcomer, Ignedus. I think his armor would look nice on our new savior.\n\nIgnedus seems to be quite careful in showing his face, but clearly quick to anger. Get in there and make some noise, as you're so comfortable doing. I expect him to respond in kind.", sourceObjective = "Defeat the void forces within the Void Acropolis to draw out Ignedus, then defeat him and take his armor.", progress = "You are a fool if you think Ignedus can be dealt with so swiftly.", completion = "You actually... I mean, of course you succeeded. Obviously, I would not choose the losing side.", sourceObjectiveStatus = "unverified-source-field" }
quests[97035] = { id = 97035, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Depose the Deranged", description = "Defeating Ignedus is impressive, I suppose, but it does not mean you're any closer to taking Val. Periculus won't let you meddle with his playthings.\n\nHe is an... eccentric one, to say the least, and dreadfully fascinated by you flesh-beings.\n\nYou'll likely find him in the darkest hole this world has to offer, carving open the livestock that Pertinax gathered.\n\nHe likes to toy with his prey, so I would advise caution.", sourceObjective = "Enter the Forgotten Depths on Val and locate Periculus, then defeat him.", progress = "I will not take command of this world while Periculus is stalking about. He... disturbs me...", completion = "So it is done? That's a relief for any living creature in the cosmos.", sourceObjectiveStatus = "unverified-source-field" }
quests[97036] = { id = 97036, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Umbral Title Bout", description = "Well then, it seems our goals are more aligned than before. You've impressed me. With Ignedus and Periculus dealt with, all that remains is my former associate.\n\nYou will find Gladius Reginax atop that high platform, observing her quarry. She already knows you're coming, so don't aim to surprise her. There's only one way up there for you anyway: through that portal in the Glacial Reservoir.\n\nI will play my part and join you. A symbol of our... collaboration.", sourceObjective = "Travel to the platform via the Glacial Reservoir and defeat Gladius Reginax.", progress = "Just one more piece to play and Val will be ours.", completion = "Well, aren't you a devious creature. How does it feel to play with pawns of your own?", sourceObjectiveStatus = "unverified-source-field" }
quests[97037] = { id = 97037, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stargrim Revelations", description = "We have a problem, {name}.\n\nThe hologem you found revealed much about our people's time on this world and who the vigilants were in life.\n\nWho they were is not the problem, but rather the possessions they carried within their chassis.\n\nPossessions now in the hands of the Soul Architect who, as far as my scouts can tell, has left Naigtal.\n\nArchmage Y'mera will explain in greater detail.", sourceObjective = "Speak to Archmage Y'mera to learn about the Hologem.", completion = "You, good. Friend of mine. Trust. For showing.\n\nWait here enough. Must go. Stop ethereal. Find--\n\n<Tul'amar cuts herself off and looks past you. Someone's coming.>", sourceObjectiveStatus = "unverified-source-field" }
quests[97071] = { id = 97071, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Frigid Welcome to Val", description = "Even with the element of surprise, we are at a disadvantage without allies.\n\nStorming Pertinax's stronghold alone would be a death sentence.\n\nTake this beacon Tala'saan gave us and return to our entry point.\n\nI will meet you there and deliver my report to Maella.\n\nLet us hope we have some sort of shelter awaiting us.", sourceObjective = "Use the Lightveil Recall Beacon to return to the Umbral Base Camp on Val.", completion = "At least the cold didn't kill you.\n\nThanks to Y'mera, we have a more stable entry point into this frozen world.\n\nHer beacon also connects back to Silvermoon, giving us a quick evacuation point should we need it.\n\nWith the surveillance beacons in place and our foothold established, we can get to work.\n\nWelcome to Val, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[97072] = { id = 97072, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Swampy Welcome to Naigtal", description = "The Nexus-Captain is just over that hill, unaware of our arrival.\n\nAttacking now would catch his army off guard... and likely result in our demise.\n\nNo matter what, we will need allies if we are to succeed.\n\nUse this beacon to return to our invasion point.\n\nBy now, Y'mera has likely brought in the rest of our forces to support us.\n\nSpeak with Maella when you arrive.", sourceObjective = "Use the Lightveil Recall Beacon to return to the Umbral Base Camp on Naigtal.", completion = "Glad to see the swamp didn't swallow you whole.\n\nY'mera's efforts have provided a more stable entry point into this world.\n\nHer beacon also connects back to Silvermoon, allowing us a quick fallback point if needed.\n\nWith the surveillance beacons in place and our foothold established, we can get to work.\n\nWelcome to Naigtal, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[97073] = { id = 97073, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rustbolt Retailer", sourceObjective = "Greetings, {name}.\n\nIn a gesture of friendship for the co-operation that this island has shown to Mechagon, Prince Erazmin has deployed this unit to provide you with items from Mechagon.\n\nYour patronage is appreciated.", sourceObjectiveStatus = "unverified-source-field" }
quests[97075] = { id = 97075, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quality Goods", sourceObjective = "Ah!\n\n<Clears throat.>\n\nWelcome to Griftah's decor emporium. After such a fruitful visit to your neighborhood, I, Griftah, have decided to stay in your wonderful neighborhood to sell items of high value to you.", sourceObjectiveStatus = "unverified-source-field" }
quests[97077] = { id = 97077, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Shot at the Dark", description = "Now that our trap is attuned, we just need to lure our prey out into the open.\n\nI have strategically... dismantled... certain parts of the projection device I obtained. Impotus should have difficulty seeing and hearing you clearly.\n\nClaim to be one of his allies and demand a meeting at once. We will hope his curiosity gets the better of him.\n\nAnd then... \n\n<Leona holds up the void-infused gem, glances at it for a moment, then nods at you.>", sourceObjective = "Interact with the projection device to lure out Impotus.", completion = "I know we wished for a more docile dignitary, but must he be this... stale?", sourceObjectiveStatus = "unverified-source-field" }
quests[97080] = { id = 97080, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Disruptions: Val", description = "We must not let up the pressure.\n\nEven now they are rebuilding from our attacks.\n\nVenture out again and show them no mercy!", sourceObjective = "Disrupt the domanaar forces on Val by completing World Quests, Events, or Treasures.", progress = "Something to report?", completion = "I knew we could rely on you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[97081] = { id = 97081, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Disruptions: Val (Heroic)", description = "We must not let up the pressure. Even now they are rebuilding from our attacks. \n\nVenture out again and again show them no mercy!", sourceObjective = "Disrupt the domanaar forces on Val by completing World Quests, Events, or Treasures.", completion = "I knew I could count on you for this task, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[97082] = { id = 97082, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dangerous Enemies: Val", description = "Our scouts have reported seeing dangerous elite creatures that are hampering our efforts. \n\nI need you to dispatch them so we can continue our primary objective.", sourceObjective = "Take out Rare and Elite enemies on Val.", completion = "I knew I could count on you for this task, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[97083] = { id = 97083, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dangerous Enemies: Val (Heroic)", description = "Our scouts have reported seeing dangerous elite creatures that are hampering our efforts. \n\nI need you to dispatch them so we can continue our primary objective.", sourceObjective = "Take out Rare and Elite enemies on Val.", progress = "Something to report?", completion = "I knew I could count on you for this task, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[97084] = { id = 97084, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Disruption: Naigtal", description = "The stench of their forges still lingers. This means they are rebuilding. \n\nYou must keep at it if you hope to disrupt their operations enough to end their threat.\n\nNow you can go. Wreak havoc.", sourceObjective = "Disrupt the Hal'hadar on Naigtal by completing World Quests, Events, or Treasures.", completion = "Oh, you are back. Was that explosion your doing?\n\nIt appears your efforts are taking a toll. The smell of smoke is replacing that wretched smell from their operation.", sourceObjectiveStatus = "unverified-source-field" }
quests[97085] = { id = 97085, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dangerous Enemies: Naigtal", description = "I hear your scouts talk of dangerous creatures and foes they have faced. \n\nIt makes me wonder if you could defeat them? Why don't you go and try? It will certainly help your efforts here.\n\nI hope to see you return mostly intact.", sourceObjective = "Take out Rare and Elite enemies on Naigtal.", completion = "You did it? Oh, I am not surprised. You do seem to be rather lucky.\n\nMaybe in time I will see enough evidence to attribute it to skill. \n\nDo you not have something else you should be about?", sourceObjectiveStatus = "unverified-source-field" }
quests[97086] = { id = 97086, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dangerous Enemies: Naigtal (Heroic)", description = "I hear your scouts talk of dangerous creatures and foes they have faced. \n\nIt makes me wonder if you could defeat them? Why don't you go and try? It will certainly help your efforts here.\n\nI hope to see you return mostly intact.", sourceObjective = "Take out Rare and Elite enemies on Naigtal.", completion = "You did it? Oh, I am not surprised. You do seem to be rather lucky.\n\nMaybe in time I will see enough evidence to attribute it to skill. \n\nDo you not have something else you should be about?", sourceObjectiveStatus = "unverified-source-field" }
quests[97087] = { id = 97087, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Disruption: Naigtal (Heroic)", description = "The stench of their forges still lingers. This means they are rebuilding. \n\nYou must keep at it if you hope to disrupt their operations enough to end their threat.\n\nNow you can go. Wreak havoc.", sourceObjective = "Disrupt the Hal'hadar on Naigtal by completing World Quests, Events, or Treasures.", completion = "Oh, you are back. Was that explosion your doing?\n\nIt appears your efforts are taking a toll. The smell of smoke is replacing that wretched smell from their operation.", sourceObjectiveStatus = "unverified-source-field" }
