quests[97128] = { id = 97128, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lair: Nymrissa Wavecaller" }
quests[97141] = { id = 97141, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spoils of the Vaults", description = "It takes de whole of our strength to keep de forces of Ula'tek from overwhelming de isle. Dat battle is waged inside the Vault of Ula'tek, against the endless tide of her children. Kill one, and two more will slither out of de venom.\n\nVenture in, {name}, and lend your power to our weary fighters. Who knows? You may even find something valuable in dat ancient, cursed place.", sourceObjective = "Participate in activities inside the Vaults of Atal'Utek.", progress = "Careful not to fall in de rivers of venom.", completion = "Dat should buy us some room to rally our strength.", sourceObjectiveStatus = "unverified-source-field" }
