quests[97213] = { id = 97213, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Candy Bucket" }
quests[97215] = { id = 97215, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Secondary Strike", description = "We have struck a major blow against our enemies. Still, they continue their assaults.\n\nDecimus and my riftwardens have targeted another world from which they launch these attacks.\n\nThe bulk of our forces have temporarily withdrawn to the Voidstorm so that we may begin our assault on this second world.\n\nOur strike team awaits us at the Howling Ridge.", sourceObjective = "Meet Riftblade Maella in the Voidstorm.", completion = "Our enemies have each established their strongholds on different worlds, forcing us to split our attention.\n\nIf we are to truly route their forces, we must strike at both and fortify our entry points.\n\nReady to breach another rift?", sourceObjectiveStatus = "unverified-source-field" }
quests[97256] = { id = 97256, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knocking Off the Top (Heroic)", description = "Even the most ruthless of creatures falter when they see their greatest champions crumble to ash.\n\nRemind our enemies here just how quickly their leaders fall!\n\nLet them know just how unrelenting and vicious you monsters of Azeroth really are! Bring me the Void Commander's Emblems and I will reward you accordingly.", sourceObjective = "Collect 4 Void Commander's Emblems from Nexus-Captain Leth'ir or Imperator Pertinax while in the Heroic world tier of Val and Naigtal.", progress = "Are you done already?", completion = "Diabolical as always. Your kind continue to remind me why I chose you to help me. \n\nAs a reward, I have procured some items that you might find useful in our future endeavors. No need to tell your allies about this.", sourceObjectiveStatus = "unverified-source-field" }
quests[97321] = { id = 97321, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slithering Spoils", description = "I've got good news and bad news.\n\nBad is that all those curios we dug up together? Melted.\n\nGood news? I've found some very interesting new poisons to work with.\n\nBut let me explain what happened...", sourceObjective = "Listen to Valeera's story.", progress = "What do you think?", completion = "It was a rookie mistake, but it wasn't all for nothing.", sourceObjectiveStatus = "unverified-source-field" }
quests[97381] = { id = 97381, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Curated Gift", description = "I have watched the effort and care you take with the other mortals of your neighborhood, here in Founder's Point. This ceaseless labor on their behalf is the sort of behavior that I encourage. There's no profit to be had for you, but that isn't a driving concern for the best of your kind.\n\nIn recognition of your efforts and status, I offer you a gift. This small device contains a piece of decor for you to place in your home. I will have another for you next week.", sourceObjective = "Accept a gift from the Last Architect.", sourceObjectiveStatus = "unverified-source-field" }
quests[97382] = { id = 97382, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Counter-Curse Bounty", description = "Every part of dis isle is cursed, {name}. When de curse of Ula'tek coalesces into a fight, dat is when it is most important to strike back. We need all de help we can get keeping it at bay.\n\nYou look strong... but you'll need better equipment if you want to stay alive.\n\nDefeat the leader of one of dese surges, and then we can discuss a reward.", sourceObjective = "Defeat a Curse Surge.", progress = "Careful not to fall in de rivers of venom.", completion = "Dat should teach dese snakes a lesson, but I can't imagine dey will take it to heart.", sourceObjectiveStatus = "unverified-source-field" }
quests[97383] = { id = 97383, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spirit Corrosion", description = "Our scouts found dis relic in one of da crypts. Maybe Er'inye knows what to do with it?", sourceObjective = "Bring the Corrosive Relic to Er'inye in the Vaults of Atal'Utek.", progress = "What's dat you got there?", completion = "Dis relic is old and powerful. I can transfer de corrosion to your spirit.", sourceObjectiveStatus = "unverified-source-field" }
quests[97384] = { id = 97384, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Spirit Corrosion", description = "One of those soulcoilers was carrying dis gem. You should show it to Er'inye.", sourceObjective = "Bring the Corrosive Bijou to Er'inye in the Vaults of Atal'Utek.", progress = "What did you find?", completion = "I can extract de corrosion from de jewel. Let's turn their power against dem.", sourceObjectiveStatus = "unverified-source-field" }
quests[97454] = { id = 97454, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seasonal Refresher: Midnight", description = "Since the opening of the Coiling Isles, things have started to get interesting again in delves.\n\nSee if our dear hosts have anything they can spare for those of us actually risking our necks and check the Delver's Guide for any updates.\n\nA quick refresher never hurt anyone.", sourceObjective = "Review the Delver's Guide and purchase seasonal supplies from Naleidea Rivergleam and Telemancer Astrandis.", progress = "Good to go?", completion = "Excellent, though there have been... developments since last we spoke.", sourceObjectiveStatus = "unverified-source-field" }
quests[97455] = { id = 97455, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of the Bell", description = "<Years beneath the waves should have erased its details, yet the bell remains remarkably well-preserved. Whatever purpose it once served, the runes carved into it were clearly meant to endure.\n\nA sense of foreboding comes over you as you consider ringing it. Maybe not.\n\nSluggs probably knows something about this item.>", sourceObjective = "Meet with Second Mate Sluggs in Tokka's Folly.\n\nProvided item:", completion = "Oh yes, I recognize this. This belonged to our dear departed Cook Leathertongue.", sourceObjectiveStatus = "unverified-source-field" }
quests[97457] = { id = 97457, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fits Like a Glove", description = "<These appear to be a large pair of hand bones, that someone has hollowed out and claimed to be gauntlets.\n\nIt's a good thing you're already wearing gauntlets, or you'd be tempted to try them on.\n\nSluggs probably knows something about this item.>", sourceObjective = "Meet with Second Mate Sluggs in Tokka's Folly.\n\nProvided item:", completion = "I... suppose they could have aided the Quartermaster with hauling up fish?", sourceObjectiveStatus = "unverified-source-field" }
quests[97458] = { id = 97458, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tackled and Boxed", description = "<An endless supply of fishing gear would be a dream for most anglers. The fact that this tacklebox screams whenever it is opened likely explains why it ended up at the bottom of the sea.\n\nAfter spending enough time with it, the screams start to echo without needing to open it at all.\n\nSluggs probably knows something about this item.>", sourceObjective = "Meet with Second Mate Sluggs in Tokka's Folly.\n\nProvided item:", completion = "Is this where all the screaming has been coming from? Birdie said it was the cannons.", sourceObjectiveStatus = "unverified-source-field" }
quests[97459] = { id = 97459, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Something Smelly", description = "<The inscription promises to not only attract spirits, but to whip them into a violent frenzy if enough is burned. That can't end well.\n\nStill, it does smell nice.\n\nSluggs probably knows something about this item.>", sourceObjective = "Meet with Second Mate Sluggs in Tokka's Folly.\n\nProvided item:", completion = "Oh my, that smells curiously like Inktail's signature scent. She always had odd taste.", sourceObjectiveStatus = "unverified-source-field" }
quests[97460] = { id = 97460, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lightly Salted", description = "<The pouch is unremarkable, but its history may not be. Ritual salts have long been used to call upon ancestors, spirits, and powers beyond the mortal world.\n\nThis salt is extra-salty, having been in the ocean. Perhaps that makes it extra-potent?\n\nSluggs probably knows something about this item.>", sourceObjective = "Meet with Second Mate Sluggs in Tokka's Folly.\n\nProvided item:", completion = "Oh... summoning salt. Cook Leathertongue always kept some around, both for flavor and defense.", sourceObjectiveStatus = "unverified-source-field" }
quests[97461] = { id = 97461, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cursed Fishing 101", description = "<Most fishing manuals concern themselves with bait, weather, and patience. This weathered tome boasts lessons on hexing one's fishing rivals and communing with the deep.\n\nYou sense you are wading into dangerous waters.\n\nSluggs probably knows something about this item.>", sourceObjective = "Meet with Second Mate Sluggs in Tokka's Folly.\n\nProvided item:", completion = "Oh no, reading on the open sea makes me queasy. But Birdie was fixated on that volume.", sourceObjectiveStatus = "unverified-source-field" }
quests[97462] = { id = 97462, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rocky Shores", description = "<This faceted ore hums with an unsettling energy. Whether it is valued more for its practical uses or its strange properties, you cannot say.\n\nYou feel compelled to lick it, though you know you shouldn't.\n\nSluggs probably knows something about this item.>", sourceObjective = "Meet with Second Mate Sluggs in Tokka's Folly.\n\nProvided item:", completion = "Just looking at it gives me a headache. What could Inktail have been doing with this?", sourceObjectiveStatus = "unverified-source-field" }
quests[97463] = { id = 97463, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Just a Normal Knife", description = "<This blade shows no signs of battle wear, only careful maintenance. Its purpose was clearly ceremonial, but for what ceremony?\n\nThe red gleam to the metal gives you a clue.\n\nSluggs probably knows something about this item.>", sourceObjective = "Meet with Second Mate Sluggs in Tokka's Folly.\n\nProvided item:", completion = "Oh dear. This most certainly belongs to the Captain.", sourceObjectiveStatus = "unverified-source-field" }
quests[97464] = { id = 97464, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Dash of Poison", description = "<The glass is thick and reinforced, suggesting the contents were considered dangerous--or valuable. The verdant liquid within glimmers as it shifts in the vial.\n\nYou think you smell something acrid and noxious about it. But it could be that this whole isle smells acrid and noxious.\n\nSluggs probably knows something about this item.>", sourceObjective = "Meet with Second Mate Sluggs in Tokka's Folly.\n\nProvided item:", completion = "How... mysterious! And green! This does seem like something Cook Leathertongue might hold onto.", sourceObjectiveStatus = "unverified-source-field" }
quests[97465] = { id = 97465, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Intended Way to Fish", description = "<It's a spear. The fishing rod is a spear.\n\nSluggs probably knows something about this item.>", sourceObjective = "Meet with Second Mate Sluggs in Tokka's Folly.\n\nProvided item:", completion = "This is a spear. What else is there to mention?\n\nI believe it belonged to Grenadier Birdie, not that she ever used it.", sourceObjectiveStatus = "unverified-source-field" }
quests[97482] = { id = 97482, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fangs for the Memories", description = "That snake monstrosity was vicious, with venom potent enough to burn through stone.\n\nWe'll want to make sure we get our hands on the best gear we can before we think about taking it on.\n\nI've got some ideas about turning that venom to our own ends, though, so we can hit the ground running.", sourceObjective = "Improve your gear until you are able to confront Azta'rec within its lair.", progress = "We'll see how it likes a taste of its own medicine.", completion = "Nicely done. It'll make a lovely pair of boots.", sourceObjectiveStatus = "unverified-source-field" }
quests[97521] = { id = 97521, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Turtle Bade It to the Water", description = "Greetings, settler!\n\nThere's a cove off the coast that my people have turned into a tavern. It's open year round, but we like to help drum up some business for them whenever we come to town. Would you care to help?", sourceObjective = "Pick up the promotional materials and advertise the underwater tavern to neighborhood locals.", completion = "I expect to see some new faces at the tavern this evening. Thank you!", sourceObjectiveStatus = "unverified-source-field" }
quests[97535] = { id = 97535, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Bargain You Won't Refuse", description = "<A voice hisses in your mind.>\n\nAm I to be another victim in your pointless conquest? I wonder... will you skin me alive and boil me in a stew? Or simply leave me to rot on a pile of your forgotten excess?\n\nWhat if I can offer you something... better? Something... delicious. The Children of Ula'tek are a blight on this world. On this we agree. Bring me proof of their demise.", sourceObjective = "Collect 12 Aqiri Mandibles from Venom Rise.", progress = "You are a vicious one after all.", completion = "I was beginning to think you had reneged...", sourceObjectiveStatus = "unverified-source-field" }
quests[97557] = { id = 97557, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tailing the Tlhapi", description = "Toxic Tlhapi. Nasty little fish.\n\nEverything's wrong about them, from their big, buggy eyes to their sweet, succulent meat...\n\n<Gills clears their throat.>\n\nNot to mention the toxicity. The seas would be much better without them fouling things up.", sourceObjective = "Bring 13 Toxic Tlhapi to Brinedrinker Gills.", progress = "Hmph. Should have asked for a lime, too.", completion = "Oh yes, they'll do much better among the crew than they would in the open ocean.\n\nI suspect Captain Tokka will be pleased.", sourceObjectiveStatus = "unverified-source-field" }
quests[97559] = { id = 97559, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Familiar Taste of Poison", description = "Surely by now even you understand the threat Ula'tek poses, yes? Her wretched power oozes forth time and time again.\n\nIf I am to do my part, I will need proof of your devotion to our... agreement, shall we call it? When next her acolytes call forth their twisted mongrels, slay them and collect their remains.", sourceObjective = "Complete Curse Surges in the Coiled Isle and recover parts from Ula'tek's faithful.", progress = "There will be no scratching of backs in this partnership as I have no hands.", completion = "Well done. \n\n<You swear you see the fish smile.>", sourceObjectiveStatus = "unverified-source-field" }
quests[97562] = { id = 97562, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Culling the Killifish", description = "Spotted Killifish. Grotesque little creatures.\n\nThe little demons swarm like insects, washing up on shores in such horrific numbers that it would take several meals to devour them all.\n\n<Gills' belly burbles audibly.>\n\nYou can do your part by collecting some for me, ridding the waters of their foul presence.", sourceObjective = "Bring 13 Spotted Killifish to Brinedrinker Gills.", progress = "Hmph. Should have asked for a crack of fresh zandalari pepper.", completion = "Oh yes, these will be far more appreciated here than swimming about the seas.\n\nI suspect Captain Tokka will be pleased.", sourceObjectiveStatus = "unverified-source-field" }
quests[97565] = { id = 97565, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tipping the Scaled", description = "<The wretched things you gathered briefly wink out of existence, returning in the same breath as one object.>\n\nGo on, take it. Carry it to the Vaults of Atal'Utek. Affix it to that dismal rod of yours and cast it into the fetid pools to draw out one of Ula'tek's pets. You do have the skill to fish anywhere, don't you?", sourceObjective = "Fish up Blightfang in the Vaults of Atal'Utek and slay it.", progress = "Is this task really so difficult?", completion = "I would hate to end our contract here when we still have so much to offer each other. I will stay close, watching and waiting.", sourceObjectiveStatus = "unverified-source-field" }
quests[97571] = { id = 97571, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dogging the Darters", description = "Dirty Darters. Ghoulish little buggers.\n\nThe way they flit about the water is so unnerving, so disquieting, one can't help but imagine them darting right down one's gullet...\n\n<Gills coughs rather loudly>\n\nYou can do your part by collecting some for me, ridding the waters of their foul presence.", sourceObjective = "Bring 13 Dirty Darters to Brinedrinker Gills.", progress = "Hmph. Should have asked for some whale butter.", completion = "Oh yes, the crew will make quick work of these squirmy little devils.\n\nI suspect Captain Tokka will be pleased.", sourceObjectiveStatus = "unverified-source-field" }
quests[97616] = { id = 97616, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corrosive Gifts: Corrosive Power", description = "<You feel a change in the air as you take this ancient volume into your hands.\n\nThough it prickles and burns your skin, your mind radiates with thoughts of the power it contains and the peril it represents.\n\nYou must know more.\n\nThere is only one place on the isle profane enough for this tome. In your mind's eye, you glimpse the Altar of Corrosion.>", sourceObjective = "Bring the Codex of the Soul Coilers to the Altar of Corrosion within the Vaults of Atal'Utek.", progress = "You know not what you meddle with.", completion = "So think you've found a way to de power of corrosion without ol' Er'inye, eh?\n\n<Er'inye scoffs.>\n\nGo on. See what it costs ya.", sourceObjectiveStatus = "unverified-source-field" }
quests[97621] = { id = 97621, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Singularity Anchor", description = "Our sojourn to this world has brought the ren'dorei an even deeper understanding of the Void than before. The domanaar with whom we share a common enemy are almost strangely generous with their knowledge. I believe they want us to become as fearsome as they are.\n\nThere is a Singularity Anchor in Stormarion Citadel. I have learned how to draw upon some of its power to craft you a powerful item.\n\nBut first, we must ensure it does not fall into the hands of our enemies.", sourceObjective = "Defend the Singularity Anchor in Stormarion Citadel.", progress = "Have you defended the anchor from the encroaching void forces?", completion = "Well done, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[97622] = { id = 97622, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Soiree to Remember", description = "You seek an audience with Saltheril? And you're wearing... that? Excuse me for a moment while I laugh into my handkerchief.\n\n<Caeris laughs lightly behind his handkerchief.>\n\nNow, let me be professional. You are cordially invited to attend Saltheril's soiree.\n\nDon't embarrass yourself, {name}. The best of Silvermoon are watching.", sourceObjective = "Participate in Saltheril's Soiree and empower Eversong's runestones.", completion = "I half expected you to run back home in tears! I hope you had a stunning time.", sourceObjectiveStatus = "unverified-source-field" }
quests[97624] = { id = 97624, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeking Legends", description = "Harandar hides wisdom in every annal of its history, {name}. You would do well to seek out its legends for yourself. I suspect you may learn something of this world and our places in it.", sourceObjective = "Discover a legend of the Haranir.", completion = "I wonder what it is that the stones showed you. I hope you found it enlightening, {name}. But remember: there is always more to learn.", sourceObjectiveStatus = "unverified-source-field" }
quests[97625] = { id = 97625, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glorious Abundance", description = "De Loa of Abundance may not be one of de four great ones, but his worshippers are certainly de most devout.\n\nSeek him out yaself. You can find him in northern Zul'Aman near Halazzi's Temple, but I also hear he's established harvest sites in Eversong Woods, Harandar, and even de land of Void through de gargantuan skymouth.\n\nIf nothing else, de rewards he grants are glorious--to de worthy, at least.", sourceObjective = "Harvest wealth for the Loa of Abundance.", progress = "Did you find de loa, hash'ura?", completion = "Heh! So ya finally met Dundun.\n\nEven de smallest are some of de greatest among de loa!", sourceObjectiveStatus = "unverified-source-field" }
quests[97640] = { id = 97640, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vaults of Atal'Utek: One Coin Too Many", sourceObjective = "Find Er'inye.", completion = "When de corrosive coins start to weigh you down, come to me.", sourceObjectiveStatus = "unverified-source-field" }
quests[97661] = { id = 97661, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Protection of the Med'jai", description = "<This amulet feels warm and smooth in your hand.\n\nAs you hold it, you feel relief from the weight of your corrosion, as if the amulet offers some protection from Ula'tek's curse.\n\nEr'inye would likely be interested in studying it.>", sourceObjective = "Bring the Med'jai Amulet to Er'inye.", completion = "Dis surprises me. Nothing in dese accursed vaults has surprised me in a long time.", sourceObjectiveStatus = "unverified-source-field" }
